window.LAW_DATA = {"id": "3amal", "title": "قانون العمل", "title_en": "LABOR LAW", "cat": "عمل وإداري", "icon": "💼", "desc": "القانون رقم 12 لسنة 2003 — علاقات العمل الفردية والجماعية وحقوق العامل وصاحب العمل.", "article_count": 269, "articles": [{"number": "الأولى", "chapter": "", "text": "يعمل بأحكام قانون العمل المرافق ."}, {"number": "الثانية", "chapter": "", "text": "تظل الأحكام الواردة بالتشريعات الخاصة ببعض فئات العمال سارية وذلك إلى أن يتم إبرام ونفاذ الاتفاقيات الجماعية بشأنها وفقا لأحكام القانون المرافق . وتعتبر المزايا الواردة بتلك التشريعات الحد الأدنى الذي يتم التفاوض على أساسه ."}, {"number": "الثالثة", "chapter": "", "text": "يستحق العاملون الذين تسرى فى شأنهم أحكام القانون المرافق علاوة سنوية دورية في تاريخ استحقاقها لا تقل عن 7 % من الأجر الأساسي الذى تحسب على أساسه اشتراكات التأمينات الإجتماعية، وذلك حتى يصدر المجلس القومى للأجور القرارات المنظمة لهذه العلاوة ."}, {"number": "الرابعة", "chapter": "", "text": "لا تخل أحكام القانون المرافق بحقوق العمال السابق لهم الحصول عليها من أجور ومزايا مستمدة من أحكام القوانين واللوائح والنظم والاتفاقيات والقرارات الداخلية السابقة على العمل بأحكامه ."}, {"number": "الخامسة", "chapter": "", "text": "تؤول إلي وزارة القوى العاملة والهجرة جميع المبالغ المحكوم بها عن مخالفة أحكام القانون المرافق ، ويكون التصرف فيها على الوجه الآتي: (أ) ثلثان يخصصان للصرف فى الأوجه وبالشروط والأوضاع التي يصدر بها قرار من وزير القوى العاملة والهجرة على الأغراض الاجتماعية وتحفيز العاملين والمشاركين في تطبيق هذا القانون . (ب) ثلث يخصص للمؤسسات الثقافية العمالية والاجتماعية العمالية التابعة للاتحاد العام لنقابات عمال مصر يوزع بينها بقرار يصدر من وزير القوى العاملة والهجرة بالاتفاق مع الاتحاد العام لنقابات عمال مصر ."}, {"number": "السادسة", "chapter": "", "text": "يستمر سريان القرارات التنفيذية لقانون العمل الصادر بالقانون رقم 137 لسنة 1981 فيما لا يتعارض مع أحكام القانون المرافق، وذلك إلى أن يصدر وزير القوى العاملة والهجرة القرارات المنفذة له فى مدة لا تجاوز تسعين يوماً من تاريخ العمل به ."}, {"number": "السابعة", "chapter": "", "text": "مع مراعاة حكم المادة الثانية من هذا القانون يلغى قانون العمل الصادر بالقانون رقم 137 لسنة 1981 كما يلغى كل حكم يخالف أحكام القانون المرافق . وتحل تسمية القانون المرافق محل عبارة قانون العمل الصادر بالقانون رقم 137 لسنة 1981 أينما وردت في القوانين والقرارات المعمول بها ."}, {"number": "الثامنة", "chapter": "", "text": "ينشر هذا القانون فى الجريدة الرسمية ويعمل به بعد تسعين يوماً من اليوم التالي لتاريخ نشره ، يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها . صدر برئاسة الجمهورية في 5 صفر 1424 هـ الموافق 7 إبريل 2003 م حسني مبارك"}, {"number": "1", "chapter": "الباب الأول", "text": "يقصد فى تطبيق أحكام هذا القانون بالمصطلحات الآتية المعاني المبينة قرين كل منها: (أ) العامل: كل شخص طبيعي يعمل لقاء أجر لدى صاحب عمل وتحت إداراته وإشرافه . (ب) صاحب العمل: كل شخص طبيعي أو اعتباري يستخدم عاملا أو أكثر لقاء أجر . (ج) الأجر : كل ما يحصل عليه العامل لقاء عمله ثابتاً كان أو متغيرا نقدا أو عينا . ويعتبر أجراً على الأخص ما يلي: 1- العمولة التي تدخل في إطار علاقة العمل . 2- النسبة المئوية ، وهى ما قد يدفع العمل مقابل ما يقوم بإنتاجه أو بيعه أو تحصيله طوال قيامه بالعمل المقرر له هذه النسبة . 3- العلاوات أيا كان سبب استحقاقها أو نوعها . 4- المزايا العينية التي يلتزم بها صاحب العمل دون أن تستلزمها مقتضيات العمل . 5- المنح ، وهى ما يعطي للعامل علاوة على أجره وما يصرف له جزاء أمانته أو كفاءته متى كانت هذه المنح مقررة في عقود العمل الفردية أو الجماعية أو فى الأنظمة الأساسية للعمل، وكذلك ما جرت العادة بمنحه متى توافرت له صفات العمومية والدوام والثبات . 6- البدل ، هو ما يعطى للعامل لقاء ظروف أو مخاطر معينة يتعرض لها فى أداء عمله . 7- نصيب العامل في الأرباح . 8- الوهبة التي يحصل عليها العامل إذا جرت العادة بدفعها وكانت لها قواعد تسمح بتحديدها ، وتعتبر في حكم الوهبة النسبة المئوية التي يدفعها العملاء مقابل الخدمة في المنشآت السياحية . ويصدر قرار من الوزير المختص بالاتفاق مع المنظمة النقابية المعنية بكيفية توزيعها على العاملين وذلك بالتشاور مع الوزير المعني . (د) العمل المؤقت : العمل الذي يدخل بطبيعته فيما بزواله صاحب العمل من نشاط وتقتضي طبيعة إنجازه مدة محددة ، أو ينصب على عمل بذاته وينتهي بانتهائه . (هـ) العمل العرضي : العمل الذي لا يدخل بطبيعته فيما يزواله صاحب العمل من نشاط ولا يستغرق إنجازه أكثر من ستة أشهر . (و) العمل الموسمي: العمل الذي يتم فى مواسم دورية متعارف عليها. (ز) الليل: الفترة ما بين غروب الشمس وشروقها . (ح) الوزير المختص: الوزير المختص بالقوى العاملة . (ط) الوزارة المختصة: الوزارة المختصة بشئون القوى العاملة ."}, {"number": "2", "chapter": "الباب الأول", "text": "فى تطبيق أحكام هذا القانون تعتبر السنة 365 يوماً ، والشهر ثلاثين يوماً إلا إذا تم الاتفاق على خلاف ذلك ."}, {"number": "3", "chapter": "الباب الثانى", "text": "يعتبر هذا القانون ، القانون العام الذي يحكم علاقات العمل ، وذلك مع مراعاة اتفاقيات العمل الجماعية وأحكام المادة (5) من هذا القانون ."}, {"number": "4", "chapter": "الباب الثانى", "text": "لا تسرى أحكام هذا القانون على: (أ) العاملين بأجهزة الدولة بما في ذلك وحدات الإدارة المحلية والهيئات العامة . (ب) عمال الخدمة المنزلية ومن فى حكمهم . (ج) أفراد أسرة صاحب العمل الذين يعولهم فعلا . وذلك ما لم يرد نص على خلاف ذلك ."}, {"number": "5", "chapter": "الباب الثانى", "text": "يقع باطلا كل شرط أو اتفاق يخالف أحكام هذا القانون ولو كان سابقا على العمل به ، إذا كان يتضمن انتقاصا من حقوق العامل المقررة فيه . ويستمر العمل بأية مزايا أو شروط أفضل تكون مقررة أو تقرر في عقود العمل الفردية أو الجماعية أو الأنظمة الأساسية أو غيرها من لوائح المنشأة، أو بمقتضى العرف . وتقع باطلة كل مصالحة تتضمن انتقاصا أو إبراء من حقوق العامل الناشئة عن عقد العمل خلال مدة سريانه أو خلال ثلاثة أشهر من تاريخ انتهائه متى كانت تخالف أحكام هذا القانون ."}, {"number": "6", "chapter": "الباب الثانى", "text": "تعفى من الرسوم القضائية فى جميع مراحل التقاضي الدعاوى الناشئة عن المنازعات المتعلقة بأحكام هذا القانون التي يرفعها العاملون والصبية المتدرجون وعمال التلمذة الصناعية أو المستحقون عن هؤلاء ، وللمحكمة فى جميع الأحوال أن تشمل حكمها بالنفاذ المعجل وبلا كفالة ولها فى حالة رفض الدعوى أن تحكم على رافعها بالمصروفات كلها أو بعضها وتعفى الفئات المشار إليها فى الفقرة السابقة من رسم الدمغة على كل الشهادات والصور التي تعطى لهم والشكاوى والطلبات التي تقدم منهم تطبيقاً لأحكام هذا القانون ."}, {"number": "7", "chapter": "الباب الثانى", "text": "تكون للمبالغ المستحقة للعامل والمستحقين عنه بمقتضى أحكام هذا القانون امتياز على جميع أموال المدين من منقول وعقار، وتستوفي مباشرة بعد المصروفات القضائية والمبالغ المستحقة للخزانة العامة . ومع ذلك يستوفي الأجر قبل غير من الحقوق المشار إليها في الفقرة السابقة ."}, {"number": "8", "chapter": "الباب الثانى", "text": "إذا تعدد أصحاب العمل كانوا مسئولين بالتضامن فيما بينهم عن الوفاء بالالتزامات الناشئة عن هذا القانون . ويكون من تنازل له صاحب العمل عن الأعمال المسندة إليه كلها أو بعضها متضامناً معه في الوفاء بجميع الالتزامات التي تفرضها أحكام هذا القانون ."}, {"number": "9", "chapter": "الباب الثانى", "text": "لا يمنع من الوفاء بجميع الالتزامات الناشئة طبقاً للقانون ، حل المنشأة أو تصفيتها أو إغلاقها أو إفلاسها . ولا يترتب على إدماج المنشأة فى غيرها أو انتقالها بالإرث أو الوصية أو الهبة أو البيع - ولو كان بالمزاد العلني - أو النزول أو الإيجار أو غير ذلك من التصرفات ، إنهاء عقود استخدام عمال المنشأة ويكون الخلف مسئولا بالتضامن مع أصحاب الأعمال السابقين عن تنفيذ جميع الالتزامات الناشئة عن هذه العقود ."}, {"number": "10", "chapter": "الباب الثانى", "text": "يصدر الوزير المختص قرارا بتحديد الجهات الإدارية المختصة بتطبيق أحكام هذا القانون ."}, {"number": "11", "chapter": "الباب الأول", "text": "تنشأ لجنة عليا لتخطيط واستخدام القوى العاملة في الداخل والخارج برئاسة الوزير المختص ، وتضم ممثلين للوزارات المعنية ، كذلك ممثلين للاتحاد العام لنقابات عمال مصر ومنظمات أصحاب الأعمال تختارهم منظماتهم بالتساوي بينهم . ويدخل في اختصاص هذه اللجنة رسم السياسة العامة لاستخدام العمالة المصرية في داخل جمهورية مصر العربية أو خارجها ، ووضع النظم والقواعد والإجراءات اللازمة لهذا الاستخدام . ويصدر بتشكيل اللجنة ونظام سير العمل بها قرار من رئيس مجلس الوزراء في مدة أقصاه ستة أشهر من تاريخ العمل بهذا القانون ."}, {"number": "12", "chapter": "الفصل الأول", "text": "مع عدم الإخلال بأحكام القانون رقم 39 لسنة 1975 بشأن تأهيل المعوقين ، على كل قادر على العمل وراغب فيه أن يتقدم بطلب لقيد اسمه بالجهة الإدارية المختصة التى يقع فى دائرتها محل إقامته مع بيان سنه ومهنته ومؤهلاته وخبرته السابقة وعلى هذه الجهة قيد تلك الطلبات بأرقام مسلسلة فور ورودها وإعطاء الطالب شهادة بحصول هذا القيد دون مقابل . وتحدد البيانات التي يجب أن تتضمنها الشهادة المشار إليها فى الفقرة السابقة بقرار من الوزير المختص ."}, {"number": "13", "chapter": "الفصل الأول", "text": "إذا كان الراغب فى العمل يمارس حرفة من الحرف التي يصدر بها قرار من الوزير المختص المشار إليها في المادة (139) من هذا القانون وجب عليه أن يرفق بطلب القيد شهادة تحدد مستوى مهارته وترخيص مزاولة الحرفة طبقا للمادة (140) من هذا القانون، وتثبت درجة مهارته في شهادة القيد . ولا يجوز تشغيل أي عامل إلا إذا كان حاصلا على هذه الشهادة ."}, {"number": "14", "chapter": "الفصل الأول", "text": "مع عدم الإخلال بأحكام القانون رقم 39 لسنة 1975 بشأن تأهيل المعوقين ، لصاحب العمل الحق فى تعيين من يقع عليه اختياره فإذا لم يكن المرشح من بين الحاصلين على شهادة القيد المشار إليها فى المادة (12) من هذا القانون، وجب عليه قيد أسمه خلال خمسة عشر يوما من إلحاقه بالعمل . ويجوز لصاحب العمل أن يستوفى احتياجاته الوظيفية والمهنية والحرفية بالنسبة للوظائف والأعمال التى خلت أو أنشئت لديه ممن ترشحهم الجهة الإدارية المختصة التي يقع في دائرتها محل عمله من المسجلين لديها مراعية أسبقية القيد ."}, {"number": "15", "chapter": "الفصل الأول", "text": "يلتزم صاحب العمل فى المنشآت القائمة وقت تطبيق أحكام هذا القانون وتلك التى تنشأ مستقبلا بأن يرسل إلى الجهة الإدارية المختصة التى يقع فى دائرتها محل العمل خلال خمسة عشرة يوماً من تاريخ العمل بهذا القانون أو من تاريخ بدأ العمل بالمنشأة - على حسب الأحوال- بياناً مفصلا بعدد العمال طبقاً لمؤهلاتهم ومهنهم وفئات أعمارهم وجنسياتهم ونوعهم والأجور التى يتقاضونها ، وعليه خلال ثلاثين يوماً من تاريخ شغل الوظيفة التي خلت لديه أن يعيد إلى الجهة الإدارية شهادة قيد العامل الصادر منها بعد استيفاء البيانات المدونة بها ، وعليه تدوين رقم شهادة القيد وتاريخها أمام اسم العامل في سجل قيد العمال بالمنشأة . وعلى صاحب العمل في المنشآت المشار إليها في الفقرة الأولى أن يرسل إلى ذات الجهة خلال شهر يناير من كل عام البيانات الآتية : (أ) ما طرأ من تعديلات على البيانات الواردة فى الفقرة السابقة . (ب) عدد الوظائف الشاغرة بسبب الإحلال والتوسعات الجديدة . (ج) بيان بتقدير الاحتياجات المتوقعة موزعة بحسب الحالة التعليمية والمهنية خلال العام التالي ."}, {"number": "16", "chapter": "الفصل الأول", "text": "لصاحب العمل الإعلان عن الوظائف الشاغرة بمختلف وسائل الإعلام وأن يعهد إلى أحد المكاتب الاستشارية بدارسة الطلبات التي تقدم إليه وإبداء الرأي أو التوصية أو المساعدة بشأن اختيار أفضل المرشحين لهذه الوظائف . ولا يجوز له تشغيل عمال عن طريق متعهد أو مقاول توريد عمال . ويجوز للوزير المختص بقرار منه الترخيص للجمعيات والمؤسسات والمنظمات النقابية بالنسبة لأعضائها بإنشاء مكاتب لتشغيل المتعطلين، وفي هذه الحالة يتعين على هذه الجهات مراعاة الأحكام الواردة في هذا الفصل والقرار المشار إليه ."}, {"number": "17", "chapter": "الفصل الأول", "text": "مع عدم الإخلال بالاتفاقيات الدولية المتعلقة بالتشغيل ، تكون مزاولة عمليات إلحاق المصريين بالعمل في الداخل أو في الخارج عن طريق: ( أ ) الوزارة المختصة . (ب) الوزارات والهيئات العامة . (ج) الاتحاد العام لنقابات عمال مصر . (د) شركات القطاع العام وقطاع الأعمال العام والقطاع الخاص المصرية فيما تبرمه من تعاقدات مع الجهات الأجنبية في حدود أعمالها وطبيعة نشاطها . (هـ) شركات المساهمة أو شركات التوصية بالأسهم أو ذات المسئولية المحدودة، بعد الحصول على ترخيص بذلك من الوزارة المختصة . (و) النقابات المهنية بالنسبة لأعضائها فقط ."}, {"number": "18", "chapter": "الفصل الأول", "text": "للمنظمات الدولية أن تزاول عمليات إلحاق المصريين للعمل خارج جمهورية مصر العربية إذا كان التعاقد مع جهات حكومية أو هيئات عامة عربية أو أجنبية ."}, {"number": "19", "chapter": "الفصل الأول", "text": "تتولى الوزارة المختصة بالتعاون مع وزارة الخارجية متابعة تنفيذ الاتفاقيات الدولية والتعاقدات المتعلقة بالعمالة المصرية في الخارج وبحث تسوية المنازعات الناشئة عن تنفيذ هذه الاتفاقيات والتعاقدات ."}, {"number": "20", "chapter": "الفصل الأول", "text": "تقدم الجهات المشار إليها في المادتين (17) ، (18) من هذا القانون إلي الوزارة المختصة نسخة من الطلب الوارد إليها من الخارج بشأن توفير فرص العمل وشروطها موثقة من السلطات المختصة ، كما تقدم نسخة من الاتفاقات وعقود العمل المبرمة متضمنة تحديد العمل والأجر المحدد له وشروط وظروف أدائه والتزامات العامل . ويكون للوزارة خلال عشرة أيام على الأكثر من تاريخ إخطارها بالاتفاقات والطلبات والعقود مستوفاة ، الاعتراض عليها في حالة عدم مناسبة الأجر أو مخالفتها للنظام العام أو الآداب العامة ، فإذا انقضت المدة المشار إليها دون اعتراض من الوزارة اعتبرت الاتفاقات والطلبات والعقود موافقاً عليها ."}, {"number": "21", "chapter": "الفصل الأول", "text": "يحظر على الجهات المشار إليها في المادة (17) من هذا القانون تقاضي أي مقابل من العامل نظير إلحاقه بالعمل، ومع ذلك يجوز تقاضي مقابل عن ذلك من صاحب العمل . واستثناء من أحكام الفقرة السابقة يجوز للشركات المشار إليها في البند (هـ) من المادة (17) من هذا القانون تقاضي مبلغ لا يجاوز (2%) من أجر العامل الذي يتم إلحاقه بالعمل وذلك عن السنة الأولى فقط كمصروفات إدارية ، ويحظر تقاضي أية مبالغ أخرى من العامل تحت أي مسمى ."}, {"number": "22", "chapter": "الفصل الأول", "text": "مع عدم الإخلال بالشروط التي يوجبها قانون شركات المساهمة والتوصية بالأسهم والشركات ذات المسئولية المحدودة ، يشترط للحصول على الترخيص المنصوص عليه في الفقرة (هـ) من المادة (17) من هذا القانون ما يأتي: 1- أن يكون المؤسسون وأعضاء مجلس الإدارة والمديرون المختصون بعمليات التشغيل من المصريين ولم يسبق الحكم على أي منهم بعقوبة جناية ، أو بعقوبة جنحة مخلة بالشرف أو الأمانة أو الآداب العامة ، ما لم يكن قد رد إليه اعتباره . 2- ألا يقل رأس مال الشركة عن مائة ألف جنيه وأن يكون مملوكاً بأكمله للمصريين . وبالنسبة للشركات التي تزاول عمليات تشغيل المصريين خارج جمهورية مصر العربية يتعين ألا يقل رأس مالها عن مائة ألف جنيه وأن تكون الأغلبية المطلقة للمؤسسين وأعضاء مجلس الإدارة من المصريين الذي يتملكون (51%) على الأقل من رأس مالها . 3- أن تقدم الشركة خطاب ضمان غير مشروط وغير قابل للإلغاء صادراً من أحد البنوك العاملة في جمهورية مصر العربية بمبلغ مائة ألف جنيه لصالح الوزارة المختصة ، وأن يكون هذا الخطاب سارياً طوال مدة سريان الترخيص ، ويتعين استكمال قيمة خطاب الضمان بمقدار ما خصم من غرامات أو تعويضات مستحقة طبقا لأحكام هذا القانون ، وذلك خلال عشرة أيام من تاريخ إخطار الشركة المرخص لها بكتاب موصى عليه مصحوب بعلم الوصول . ويكون الترخيص لمدة خمس سنوات قابلة للتجديد وفقاً للقواعد والإجراءات التي يصدر بها قرار من الوزير المختص وذلك مقابل أداء الرسم الذي يحدده لمنح الترخيص أو تجديده بما لا يجاوز خمسة آلاف جنيه . ومع ذلك يجوز للوزير المختص وقف إصدار تراخيص جديدة أو تجديد التراخيص القائمة في ضوء احتياجات سوق العمل الفعلية ."}, {"number": "23", "chapter": "الفصل الأول", "text": "يلغى الترخيص بقرار من وزير المختص عند ثبوت أي من الحالات الآتية: 1- فقد الشركة شرطاً من شروط الترخيص . 2- تقاضي الشركة أية مبالغ من العامل نظير تشغيله بالمخالفة لأحكام هذا الفصل . 3- حصول الشركة على الترخيص أو تجديده أو عدم اعتراض الوزارة على اتفاق أو عقد عمل بناء على ما قدمته من بيانات غير صحيحة . ويجوز بقرار من الوزير المختص إلغاء الترخيص فى حالة ثبوت مخالفة الشركة لحكم من الأحكام الجوهرية الواردة فى القرارات الصادرة تنفيذا لأحكام هذا الفصل . وللوزير المختص إيقاف نشاط الشركة مؤقتا إذا نسب إليها بناء على أسباب جدية أي من الحالات المبينة فى هذه المادة ، وذلك لحين الفصل في مدى ثبوت تلك الحالات أو حين زوال المخالفة في الحالة المنصوص عليها في الفقرة السابقة . ولا يخل إلغاء الترخيص في أي من الحالات المبينة في هذه المادة بالمسئولية الجنائية أو المدنية أو التأديبية ."}, {"number": "24", "chapter": "الفصل الأول", "text": "يصدر الوزير المختص القرارات اللازمة لتنفيذ أحكام هذا الفصل ، وعلى الأخص القرارات المتعلقة بواجبات الشركات المرخص لها بالعمل في مجال التشغيل ، والشروط الواجب توافرها في مقر الشركة وتنظيم إجراءات العمل في هذا النشاط ، وتحديد السجلات التي يتعين إمساكها واللازمة لمباشرة عملها وقواعد القيد فيها والرقابة والتفتيش عليها ، والشروط الواجب توافرها في الإعلانات التي تنشر في جمهورية مصر العربية عن فرص العمل ، وكذلك تحديد أسلوب ووسيلة إخطار الجهات المنصوص عليها في المادتين (17) ، (18) من هذا القانون باعتراض الوزارة وذلك كله خلال ستين يوماً من تاريخ العمل بهذا القانون ."}, {"number": "25", "chapter": "الفصل الأول", "text": "يستثنى من تطبيق أحكام هذا الفصل ما يأتي: ( أ) الأعمال العرضية . (ب) الوظائف الرئيسية التي يعتبر شاغلوها وكلاء مفوضين عن أصحاب الأعمال . وللوزير المختص أن يصدر قراراً بسريان أحكام هذا الفصل على كل أو بعض الأعمال والوظائف والفئات المشار إليها في البندين السابقين ."}, {"number": "26", "chapter": "الفصل الأول", "text": "تتولى الوزارة المختصة رسم سياسة ومتابعة تشغيل العمالة غير المنتظمة وعلى الأخص عمال الزراعة الموسميين وعمال البحر وعمال المناجم والمحاجر وعمال المقاولات . ويصدر الوزير المختص بالتشاور مع الوزراء المعنيين والاتحاد العام لنقابات عمال مصر القرارات الخاصة بتحديد القواعد المنظمة لتشغيل هذه الفئات ، واشتراطات السلامة والصحة المهنية والانتقال والإعاشة الواجب اتخاذها بشأنهم، واللوائح المالية والإدارية التي تنظم هذا التشغيل ."}, {"number": "27", "chapter": "الفصل الثانى", "text": "يخضع استخدام الأجانب في جميع منشآت القطاع الخاص ووحدات القطاع العام وقطاع الأعمال العام والهيئات العامة والإدارة المحلية والجهاز الإداري للدولة للأحكام الواردة في هذا الفصل ، وذلك مع مراعاة شرط المعاملة بالمثل . ويحدد الوزير المختص حالات إعفاء الأجانب من هذا الشرط ."}, {"number": "28", "chapter": "الفصل الثانى", "text": "لا يجوز للأجانب أن يزاولوا عملاً إلا بعد الحصول على ترخيص بذلك من الوزارة المختصة ، وأن يكون مصرحاً لهم بدخول البلاد والإقامة بقصد العمل . ويقصد بالعمل في تطبيق أحكام هذا الفصل كل عمل تابع أو أية مهنة أو حرفة بما في ذلك العمل في الخدمة المنزلية ."}, {"number": "29", "chapter": "الفصل الثانى", "text": "يحدد الوزير المختص بقرار منه شروط الحصول على الترخيص بالعمل المشار إليه في المادة السابقة وإجراءاته والبيانات التي يتضمنها وإجراءات تجديده والرسم الذي يحصل عنه بما لا يقل عن ألف جنيه مصري . كما يحدد حالات إلغاء الترخيص قبل انتهاء مدته وحالات إعفاء الأجانب من شرط الحصول عليه . ويلتزم كل من يستخدم أجنبياً أعفى من شرط الحصول على الترخيص بأن يخطر الجهة الإدارية المختصة بذلك الاستخدام خلال سبعة أيام من مزاولة الأجنبي للعمل ، وكذلك عند انتهاء خدمته لديه ."}, {"number": "30", "chapter": "الفصل الثانى", "text": "يحدد الوزير المختص بقرار منه المهن والأعمال والحرف التي يحظر على الأجانب الاشتغال بها، كما يحدد النسبة القصوى لاستخدامهم في المنشآت والجهات المبينة في المادة (27) من هذا القانون ."}, {"number": "31", "chapter": "الباب الثانى", "text": "تسرى أحكام هذا الباب على العقد الذي يتعهد بمقتضاه عامل بأن يعمل لدى صاحب العمل وتحت إداراته أو أشرافه لقاء أجر ."}, {"number": "32", "chapter": "الباب الثانى", "text": "يلتزم صاحب العمل بتحرير عقد العمل كتابة باللغة العربية من ثلاث نسخ ، يحتفظ صاحب العمل بواحدة ويسلم نسخة للعامل وتودع الثالثة مكتب التأمينات الاجتماعية المختص . ويجب أن يتضمن العقد على الأخص البيانات الآتية: (أ) اسم صاحب العمل وعنوان محل العمل . (ب) اسم العامل ومؤهله ومهنته أو حرفته ورقمه التأميني ومحل أقامته وما يلزم لإثبات شخصيته . (ج) طبيعة ونوع العمل محل التعاقد . (د) الأجر المتفق عليه وطريقة وموعد أدائه وكذلك سائر المزايا النقدية والعينية المتفق عليها . فإذا لم يوجد عقد مكتوب ، للعامل وحده إثبات حقوقه بكافة طرق الإثبات . ويعط صاحب العمل العامل إيصالا بما يكون قد أودعه لديه من أوراق وشهادات ."}, {"number": "33", "chapter": "الباب الثانى", "text": "تحدد مدة الاختبار فى عقد العمل ، ولا يجوز تعيين العامل تحت الاختبار لمدة تزيد على ثلاثة أشهر أو تعينيه تحت الاختبار أكثر من مرة واحدة عند صاحب عمل واحد ."}, {"number": "34", "chapter": "الباب الثالث", "text": "ينشأ مجلس قومي للأجور برئاسة وزير التخطيط يختص بوضع الحد الأدنى للأجور علي المستوي القومي بمراعاة نفقات المعيشة ، وبإيجاد الوسائل والتدابير التي تكفل تحقيق التوازن بين الأجور والأسعار . كما يختص المجلس بوضع الحد الأدنى للعلاوات السنوية الدورية بما لا يقل عن (7 %) من الأجر الأساسي الذي تحسب على أساسه اشتراكات التأمينات الاجتماعية . وفي حالة تعرض المنشأة لظروف اقتصادية يتعذر معها صرف العلاوة الدورية المشار إليها ، يعرض الأمر على المجلس القومي للأجور لتقرير ما يراه ملائماً مع ظروفها في خلال ثلاثين يوماً من تاريخ عرض الأمر عليه . ويصدر رئيس مجلس الوزراء خلال ستين يوماً من تاريخ العمل بهذا القانون قراراً بتشكيل هذا المجلس ويضم في عضويته الفئات الآتية: 1- أعضاء بحكم وظائفهم أو خبراتهم . 2- أعضاء يمثلون منظمات أصحاب الأعمال تختارهم هذه المنظمات . 3- أعضاء يمثلون الاتحاد العام لنقابات عمال مصر يختارهم الاتحاد . ويراعي أن يكون عدد أعضاء الفئة الأولى مساوياً لعدد أعضاء الفئتين الثانية والثالثة معاً وأن يتساوى عدد أعضاء كل من الفئتين الثانية والثالثة . ويحدد في قرار تشكيل المجلس اختصاصاته الأخرى ونظام العمل به ."}, {"number": "35", "chapter": "الباب الثالث", "text": "يحظر التمييز في الأجور بسبب اختلاف الجنس أو الأصل أو اللغة أو الدين أو العقيدة ."}, {"number": "36", "chapter": "الباب الثالث", "text": "يحدد الأجر وفقاً لعقد العمل الفردي أو اتفاقية العمل الجماعي أو لائحة المنشأة ، فإذا لم يحدد الأجر بأي من هذه الطرق استحق العامل أجر المثل إن وجد ، وإلا قدر الأجر طبقاً لعرف المهنة في الجهة التي يؤدي فيها العمل، فإن لم يوجد عرف تولت المحكمة العمالية المنصوص عليها في المادة (71) من هذا القانون تقدير الأجر وفقاً لمقتضيات العدالة، وذلك كله مع مراعاة حكم المادتين ( 34 ، 35) من هذا القانون ."}, {"number": "37", "chapter": "الباب الثالث", "text": "إذا تم الاتفاق على تحديد الأجر بالإنتاج أو بالعمولة وجب ألا يقل ما يحصل عليه العامل عن الحد الأدنى للأجور ."}, {"number": "38", "chapter": "الباب الثالث", "text": "تؤدى الأجور وغيرها من المبالغ المستحقة للعامل بالعملة المتداولة قانوناً في أحد أيام العمل وفي مكانه ، مع مراعاة الأحكام التالية: ( أ ) العمال المعينون بأجر شهري تؤدي أجورهم مرة على الأقل في الشهر . (ب) إذا كان الأجر بالإنتاج واستلزم العمل مدة تزيد على أسبوعين وجب أن يحصل العامل كل أسبوع على دفعة تحت الحساب تتناسب مع ما أتمه من العمل وأن يؤدى له باقي الأجر خلال الأسبوع التالي لتسليم ما كلف به . (ج) في غير ما ذكر في البندين السابقين تؤدى للعمال أجورهم مرة كل أسبوع على الأكثر ما لم يتفق على غير ذلك . (د) إذا انتهت علاقة العمل يؤدى صاحب العمل للعامل أجره وجميع المبالغ المستحقة له فوراً إلا إذا كان العامل قد ترك العمل من تلقاء نفسه فيجب في هذه الحالة على صاحب العمل أداء أجر العامل وجميع مستحقاته في مدة لا تجاوز سبعة أيام من تاريخ مطالبة العامل بهذه المستحقات ."}, {"number": "39", "chapter": "الباب الثالث", "text": "يكون حساب متوسط الأجر اليومى لعمال الإنتاج أو العمال الذين يتقاضون أجوراً ثابتة مضافاً إليها عمولة أو نسبة مئوية على أساس متوسط ما تقاضاه العامل عن أيام العمل الفعلية في السنة الأخيرة أو عن المدة التي اشتغلها إن قلت عن ذلك مقسوماً على عدد أيام العمل الفعلية عن ذات الفترة ."}, {"number": "40", "chapter": "الباب الثالث", "text": "يحظر على صاحب العمل أن ينقل عاملاً بالأجر الشهري إلى فئة عمال المياومة أو العمال المعينين بالأجر الأسبوعي أو بالساعة أو بالإنتاج إلا بموافقة العامل عند نقله كتابة ، ويكون للعامل في هذه الحالة جميع الحقوق التي اكتسبها في المدة التي قضاها بالأجر الشهرى ."}, {"number": "41", "chapter": "الباب الثالث", "text": "إذا حضر العامل إلى مقر عمله في الوقت المحدد للعمل ، وكان مستعداً لمباشرة عمله وحالت دون ذلك أسباب ترجع إلى صاحب العمل ، اعتبر كأنه أدى عمله فعلاً واستحق أجره كاملاً . أما إذا حضر وحالت بينه وبين مباشرة عمله أسباباً قهرية خارجة عن إرادة صاحب العمل استحق نصف أجره ."}, {"number": "42", "chapter": "الباب الثالث", "text": "لا يجوز لصاحب العمل إلزام العامل بشراء أغذية أو سلع أو خدمات من محال معينة أو مما ينتجه صاحب العمل من سلع أو يقدمه من خدمات ."}, {"number": "43", "chapter": "الباب الثالث", "text": "لا يجوز لصاحب العمل أن يقتطع من أجر العامل أكثر من (10%) وفاء لما يكون قد أقرضه من مال أثناء سريان العقد أو أن يتقاضى أية فائدة عن هذه القروض ، ويسرى ذلك الحكم على الأجور المدفوعة مقدماً ."}, {"number": "44", "chapter": "الباب الثالث", "text": "مع مراعاة أحكام المواد (75 ، 76 ، 77) من قانون تنظيم بعض أوضاع وإجراءات التقاضى فى مسائل الأحوال الشخصية الصادر بالقانون رقم 1 لسنة 2000 ، لا يجوز في جميع الأحوال الاستقطاع أو الحجز أو النزول عن الأجر المستحق للعامل لأداء أي دين إلا في حدود (25%) من هذا الأجر ، ويجوز رفع نسبة الخصم إلي (50%) في حالة دين النفقة . وعند التزاحم يقدم دين النفقة ، ثم ما يكون مطلوباً لصاحب العمل بسبب ما أتلفه العامل من أدوات أو مهمات ، أو استرداداً لما صرف إليه بغير وجه حق ، أو ما وقع على العامل من جزاءات . ويشترط لصحة النزول عن الأجر في حدود النسبة المقررة بهذه المادة أن تصدر به موافقة مكتوبة من العامل . وتحسب النسبة المشار إليها في الفقرة الأولى من هذه المادة بعد استقطاع ضريبة الدخل على الأجر ، وقيمة المبالغ المستحقة وفقاً لقوانين التأمين الاجتماعي ، وما يكون صاحب العمل قد أقرضه للعامل فى حدود النسبة المنصوص عليها في المادة السابقة ."}, {"number": "45", "chapter": "الباب الثالث", "text": "لا تبرأ ذمة صاحب العمل من الأجر إلا إذا وقع العامل بما يفيد استلام الأجر في السجل المعد لذلك أو في كشوف الأجور ، على أن تشمل بيانات هذه المستندات مفردات الأجر ."}, {"number": "46", "chapter": "الباب الثالث", "text": "مع مراعاة حكم المادة السابقة ، يسلم صاحب العمل إلي عماله من الأطفال أجورهم أو مكافآتهم أو غير ذلك ما يستحقونه قانونا ، ويكون هذا التسليم مبرئا لذمته ."}, {"number": "47", "chapter": "الباب الرابع", "text": "تكون مدة الأجازة السنوية 21 يوما بأجر كامل لمن أمضي في الخدمة سنة كاملة ، تزاد إلي ثلاثين يوما متي أمضي العامل في الخدمة عشر سنوات لدى صاحب عمل أو أكثر ، كما تكون الأجازة لمدة ثلاثين يوما في السنة لمن تجاوز سن الخمسين ، ولا يدخل في حساب الإجازة أيام عطلات الأعياد والمناسبات الرسمية والراحة الأسبوعية . وإذا قلت مدة خدمة العامل عن سنة استحق أجازة بنسبة المدة التي قضاها في العمل بشرط أن يكون قد أمضى ستة أشهر في خدمة صاحب العمل . وفي جميع الأحوال تزاد مدة الأجازة السنوية سبعة أيام للعمال الذين يعملون في الأعمال الصعبة أو الخطرة أو المضرة بالصحة أو في المناطق النائية والتي يصدر بتحديدها قرار من الوزير المختص بعد أخذ رأي الجهات المعنية . ومع مراعاة حكم الفقرة الثانية من المادة (48) من هذا القانون لا يجوز للعامل النزول عن أجازته ."}, {"number": "48", "chapter": "الباب الرابع", "text": "يحدد صاحب العمل مواعيد الأجازة السنوية حسب مقتضيات العمل وظروفه ، ولا يجوز قطعها إلا لأسباب قوية تقتضيها مصلحة العمل . ويلتزم العامل بالقيام بالإجازة في التاريخ وللمدة التي حددها صاحب العمل وإذا رفض العامل كتابة القيام بالإجازة سقط حقه في اقتضاء مقابلها . وفي جميع الأحوال يجب أن يحصل العامل على أجازة سنوية مدتها خمسة عشر يوماً ، منها ستة أيام متصلة على الأقل، ويلتزم صاحب العمل بتسوية رصيد الأجازات أو الأجر المقابل له كل ثلاث سنوات على الأكثر فإذا انتهت علاقة العمل قبل استنفاد العامل رصيد أجازته السنوية استحق الأجر المقابل لهذا الرصيد . ولا يجوز تجزئة الأجازة أو ضمها أو تأجيلها بالنسبة للأطفال ."}, {"number": "49", "chapter": "الباب الرابع", "text": "للعامل الحق في تحديد موعد أجازته السنوية إذا كان متقدماً لأداء الامتحان في إحدى مراحل التعليم بشرط أن يخطر صاحب العمل قبل قيامه بالأجازة بخمسة عشر يوماً على الأقل ."}, {"number": "50", "chapter": "الباب الرابع", "text": "لصاحب العمل أن يحرم العامل من أجره عن مدة الأجازة ، أو يسترد ما أداه من أجر عنها ، إذا ثبت اشتغاله خلالها لدى صاحب عمل آخر، وذلك دون إخلال بالجزاء التأديبي ."}, {"number": "51", "chapter": "الباب الرابع", "text": "للعامل أن ينقطع عن العمل لسبب عارض لمدة لا تتجاوز ستة أيام خلال السنة ، وبحد أقصى يومان في المرة الواحدة ، وتحسب الأجازة العارضة من الأجازة السنوية المقررة للعامل ."}, {"number": "52", "chapter": "الباب الرابع", "text": "للعامل الحق في أجازة بأجر كامل في الأعياد التي يصدر بتحديدها قرار من الوزير المختص بحد أقصى ثلاثة عشر يوماً في السنة . ولصاحب العمل تشغيل العامل في هذه الأيام إذا اقتضت ظروف العمل ذلك ، ويستحق العامل في هذه الحالة بالإضافة إلى أجره عن هذا اليوم مثلى هذا الأجر ."}, {"number": "53", "chapter": "الباب الرابع", "text": "للعامل الذي أمضى في خدمة صاحب العمل خمس سنوات متصلة الحق في أجازة بأجر كامل لمدة شهر لأداء فريضة الحج أو زيارة بيت المقدس ، وتكون هذه الأجازة مرة واحدة طوال مدة خدمته ."}, {"number": "54", "chapter": "الباب الرابع", "text": "للعامل الذي يثبت مرضه الحق في أجازة مرضية تحددها الجهة الطبية المختصة ، ويستحق العامل خلالها تعويضاً عن الأجر وفقاً لما يحدده قانون التأمين الاجتماعي . ويكون للعامل الذي يثبت مرضه في المنشآت الصناعية التي تسرى في شأنها أحكام المادتين (1) ، (8) من القانون رقم 21 لسنة 1958 في شأن تنظيم الصناعة وتشجيعها ، الحق في أجازة مرضية كل ثلاث سنوات تقضى في الخدمة على أساس شهر بأجر كامل ثم ثمانية أشهر بأجر يعادل (75%) من أجره ثم ثلاثة أشهر بدون أجر ، وذلك إذا قررت الجهة الطبية المختصة احتمال شفائه . وللعامل أن يستفيد من متجمد أجازته السنوية إلى جانب ما يستحقه من أجازة مرضية ، كما له أن يطلب تحويل الأجازة المرضية إلى أجازة سنوية إذا كان له رصيد يسمح بذلك ."}, {"number": "55", "chapter": "الباب الرابع", "text": "مع مراعاة ما ورد بالمادة (49) من هذا القانون ، تحدد اتفاقيات العمل الجماعية أو لوائح العمل بالمنشأة الشروط والأوضاع الخاصة بالأجازات الدراسية مدفوعة الأجر التي تمنح للعمال ."}, {"number": "56", "chapter": "الفصل الأول", "text": "يجب على العامل: (أ) أن يؤدى بنفسه الواجبات المنوطة به بدقة وأمانة ، وذلك وفقاً لما هو محدد بالقانون ولوائح العمل وعقود العمل الفردية والجماعية، وأن ينجزها فى الوقت المحدد، وأن يبذل فيها عناية الشخص المعتاد . (ب) أن ينفذ أوامر وتعليمات صاحب العمل الخاصة بتنفيذ الواجبات التي تدخل فى نطاق العمل المنوط به، إذا لم يكن فى هذه الأوامر والتعليمات ما يخالف العقد أو القانون أو اللوائح أو الآداب العامة ولم يكن في تنفيذها ما يعرض للخطر . (ج) أن يحافظ على مواعيد العمل ، وأن يتبع الإجراءات المقررة فى حالة التغيب عن العمل أو مخالفة مواعيده . (د) أن يحافظ على ما يسلمه إليه صاحب العمل من أدوات أو أجهزة أو مستندات أو أية أشياء أخرى ، وأن يقوم بجميع الأعمال اللازمة لسلامتها ، ويلتزم بأن يبذل فى ذلك عناية الشخص المعتاد . (هـ) أن يحسن معاملة عملاء صاحب العمل . (و) أن يحترم رؤساءه وزملاءه فى العمل ، وأن يتعاون معهم بما يحقق مصلحة المنشأة التي يعمل بها . (ز) أن يحافظ على كرامة العمل ، وأن يسلك المسلك اللائق به . (ح) أن يراعى النظم الموضوعة للمحافظة على سلامة المنشأة وأمنها . (ط) أن يحافظ على أسرار العمل فلا يفشى المعلومات المتعلقة بالعمل متى كانت سرية بطبيعتها أو وفقاً للتعليمات الكتابية الصادرة من صاحب العمل . (ى) أن يخطر جهة العمل بالبيانات الصحيحة المتعلقة بمحل إقامته وحالته الاجتماعية وموقفه من أداء الخدمة العسكرية والبيانات الأخرى التي تتطلب القوانين والنظم إدراجها فى السجل الخاص به وبكل تغيير يطرأ على بيان من البيانات السابقة فى المواعيد المحددة لذلك . (ك) أن يتبع النظم التى يضعها صاحب العمل لتنمية وتطوير مهاراته وخبراته مهنياً وثقافياً أو تأهيله لقيام بعمل يتفق مع التطور التقني في المنشأة بالاشتراك مع المنظمات النقابية المختصة ."}, {"number": "57", "chapter": "الفصل الأول", "text": "يحظر على العامل أن يقوم بنفسه أو بواسطة غيره بالأعمال الآتية: (أ) الاحتفاظ لنفسه بأصل أية ورقة أو مستند خاص بالعمل . (ب) العمل للغير سواء بأجر أو بدون أجر إذا كان فى قيامه بهذا العمل ما يخل بحسن أداؤه لعمله أو لا يتفق مع كرامة العمل أو يمكن الغير أو يساعده على التعرف على أسرار المنشأة أو منافسة صاحب العمل . (ج) ممارسة نشاط مماثل للنشاط الذي يمارسه صاحب العمل أثناء مدة سريان عقده ، أو الاشتراك في نشاط من هذا القبيل ، سواء بصفته شريكاً أو عاملاً . (د) الاقتراض من عملاء صاحب العمل أو ممن يمارسون نشاطاً مماثلاً للنشاط الذي يمارسه صاحب العمل ولا يسرى هذا الحظر على الاقتراض من المصارف . (هـ) قبول هدايا أو مكافآت أو عمولات أو مبالغ أو أشياء أخرى بأية صفة كانت بمناسبة قيامه بواجباته بغير رضاء صاحب العمل . (و) جمع نقود أو تبرعات أو توزيع منشورات أو جمع توقيعات أو تنظيم اجتماعات داخل مكان العمل بدون موافقة صاحب العمل مع مراعاة ما تقضى به أحكام القوانين المنظمة للنقابات العمالية ."}, {"number": "58", "chapter": "الفصل الثانى", "text": "على صاحب العمل أن يضع لائحة تنظيم العمل والجزاءات التأديبية موضحاً بها قواعد تنظيم العمل والجزاءات التأديبية مصدقاً عليها من الجهة الإدارية المختصة ، وعلى هذه الجهة أخذ رأى المنظمة النقابية التي يتبعها عمال المنشأة قبل التصديق على اللائحة ، فإذا لم تقم الجهة الإدارية بالتصديق أو الاعتراض على اللائحة خلال ثلاثين يوماً من تاريخ تقديمها اعتبرت نافذة ، وللوزير المختص أن يصدر بقرار منه أنظمة نموذجية للوائح والجزاءات لكي يسترشد بها أصحاب الأعمال . وعلى صاحب العمل في حالة استخدام عشرة عمال فأكثر أن يضع هذه اللائحة في مكان ظاهر ."}, {"number": "59", "chapter": "الفصل الثانى", "text": "يشترط في الفعل الذي تجوز مساءلة العامل عنه تأديبياً أن يكون ذا صلة بالعمل . وتحدد لائحة الجزاءات المخالفات والجزاءات المقررة لها مما هو منصوص عليه في المادة (60) من هذا القانون ، وبما يحقق تناسب الجزاء مع المخالفة . ولا يجوز توقيع جزاء تأديبي على العامل بعد تاريخ الانتهاء من التحقيق في المخالفة بأكثر من ثلاثين يوماً ."}, {"number": "60", "chapter": "الفصل الثانى", "text": "الجزاءات التأديبية التي يجوز توقيعها على العامل وفقاً للوائح تنظيم العمل والجزاءات التأديبية في كل منشأة هى: 1- الإنذار . 2- الخصم من الأجر . 3- تأجيل موعد استحقاق العلاوة السنوية لمدة لا تجاوز ثلاثة أشهر . 4- الحرمان من جزء من العلاوة السنوية بما لا يجاوز نصفها . 5- تأجيل الترقية عند استحقاقها لمدة لا تزيد على سنة . 6- خفض الأجر بمقدار علاوة على الأكثر . 7- الخفض إلى وظيفة في الدرجة الأدنى مباشرة دون إخلال بقيمة الأجر الذي كان يتقاضاه . 8- الفصل من الخدمة وفقاً لأحكام هذا القانون ."}, {"number": "61", "chapter": "الفصل الثانى", "text": "لا يجوز لصاحب العمل أن يوقع جزاء الخصم على العامل عن المخالفة الواحدة بما يزيد على أجر خمسة أيام ، ولا يجوز أن يقتطع من أجر العامل وفاء للجزاءات التي يوقعها أكثر من أجر خمسة أيام في الشهر الواحد . وإذا حدد الخصم بنسبة محددة من الأجر اعتبر أن المقصود بذلك هو الأجر الأساسي اليومي للعامل ."}, {"number": "62", "chapter": "الفصل الثانى", "text": "لا يجوز لصاحب العمل توقيع أكثر من جزاء واحد عن المخالفة الواحدة ، كما لا يجوز له الجمع بين اقتطاع جزء من أجر العامل تطبيقاً لحكم المادة (61) من هذا القانون وبين أي جزاء مالي إذا زاد ما يجب اقتطاعه على أجر خمسة أيام في الشهر الواحد ."}, {"number": "63", "chapter": "الفصل الثانى", "text": "يجوز تشديد الجزاء إذا عاد العامل إلى ارتكاب مخالفة جديدة من نوع المخالفة التي سبق مجازاة العامل عنها ، متى وقعت المخالفة الجديدة خلال ستة أشهر من تاريخ إبلاغ العامل بتوقيع الجزاء السابق ."}, {"number": "64", "chapter": "الفصل الثانى", "text": "يحظر توقيع جزاء على العامل إلا بعد إبلاغه كتابة بما نسب إليه وسماع أقواله وتحقيق دفاعه وإثبات ذلك في محضر يودع في ملفه الخاص ، على أن يبدأ التحقيق خلال سبعة أيام على الأكثر من تاريخ اكتشاف المخالفة ، وللمنظمة النقابية التي يتبعها العامل أن تندب ممثلاُ عنها لحضور التحقيق . ويجوز في المخالفات التي يعاقب عليها بالإنذار أو الخصم من الأجر الذي لا يزيد مقداره على أجر يوم واحد أن يكون التحقيق شفاهه ، على أن يثبت مضمونه في القرار الذي يقضي بتوقيع الجزاء . وفي جميع الحالات يشترط أن يكون القرار الصادر بتوقيع الجزاء مسبباً ."}, {"number": "65", "chapter": "الفصل الثانى", "text": "لصاحب العمل أن يحقق مع العامل بنفسه ، أو أن يعهد بالتحقيق إلى إدارة الشئون القانونية أو أي شخص آخر من ذوى الخبرة في موضوع المخالفة أو أحد العاملين بالمنشأة بشرط ألا يقل المستوى الوظيفى للمحقق عن مستوى العامل الذى يحقق معه ."}, {"number": "66", "chapter": "الفصل الثانى", "text": "لصاحب العمل أن يوقف العامل عن عمله مؤقتاً لمدة لا تزيد على ستين يوماً مع صرف أجره كاملاً إذا اقتضت مصلحة التحقيق ذلك أو طلب من المحكمة العمالية المشار إليها في المادة (71) من هذا القانون فصله من الخدمة . استبدلت عبارة \" المحكمة العمالية \" بعبارة \" اللجنة \" بالقانون رقم 180 لسنة 2008 اينما وردت فى نصوص قانون العمل رقم 12 لسنة 2003"}, {"number": "67", "chapter": "الفصل الثانى", "text": "إذا اتهم العامل بارتكاب جناية أو بارتكاب جنحة مخلة بالشرف أو الأمانة أو الآداب العامة أو اتهم بارتكاب أي جنحة داخل دائرة العمل جاز لصاحب العمل وقفه مؤقتاً ، وعليه أن يعرض الأمر على المحكمة العمالية المشار إليها في المادة (71) من هذا القانون خلال ثلاثة أيام من تاريخ الوقف . وعلى المحكمة العمالية أن تبت في الحالة المعروضة عليها خلال سبعة أيام من تاريخ العرض ، فإذا وافقت على الوقف يصرف للعامل نصف أجره ، أما في حالة عدم الموافقة على الوقف يصرف أجر العامل كاملاً من تاريخ وقفه . فإذا رأت السلطة المختصة عدم تقديم العامل للمحاكمة الجنائية أو قدم للمحاكمة وقضى ببراءته وجب إعادته للعمل مع تسوية مستحقاته كاملة وإلا اعتبر عدم إعادته فصلاً تعسفياً . وإذا ثبت أن اتهام العامل كان بتدبير صاحب العمل أو من يمثله وجب أداء باقي أجره عن مدة الوقف ."}, {"number": "68", "chapter": "الفصل الثانى", "text": "يكون الاختصاص بتوقيع جزاء الفصل من الخدمة للجنة المشار إليها في المادة (71) من هذا القانون . ويكون توقيع باقي الجزاءات التأديبية لصاحب العمل أو من يفوضه لذلك . ويكون لمدير المنشأة توقيع جزاءي الإنذار والخصم من الأجر لمدة لا تجاوز ثلاثة أيام ."}, {"number": "69", "chapter": "الفصل الثانى", "text": "لا يجوز فصل العامل إلا إذا ارتكب خطأ جسيماً ، ويعتبر من قبيل الخطأ الجسيم الحالات الآتية: 1- إذا ثبت انتحال العامل لشخصية غير صحيحة أو قدم مستندات مزورة . 2- إذا ثبت ارتكاب العامل لخطأ نشأت عنه أضرار جسيمة لصاحب العمل بشرط أن يبلغ صاحب العمل الجهات المختصة بالحادث خلال أربعة وعشرين ساعة من وقت علمه بوقوعه . 3- إذا تكرر من العامل عدم مراعاة التعليمات اللازم إتباعها لسلامة العمال والمنشأة - بشرط أن تكون هذه التعليمات مكتوبة ومعلنة فى مكان ظاهر - رغم التنبيه عليه كتابة بمراعاة ذلك . 4- إذا تغيب العامل بدون مبرر مشروع أكثر من عشرين يوماً متقطعة خلال السنة الواحدة أو أكثر من عشرة أيام متتالية ، على أن يسبق الفصل إنذار كتابي بخطاب موصى عليه بعلم الوصول من صاحب العمل للعامل بعد غيابه عشرة أيام فى الحالة الأولى ، وبعد غيابه خمسة أيام في الحالة الثانية . 5- إذا ثبت أن العامل أفشى أسرار المنشأة التي يعمل بها أدت إلى إحداث أضرار جسيمة بالمنشأة . 6- إذا قام العامل بمنافسة صاحب العمل في ذات نشاطه . 7- إذا وجد العامل أثناء ساعات العمل في حالة سكر بين أو متأثرا بما تعاطاه من مادة مخدرة . 8- إذا ثبت اعتداء العامل علي صاحب العمل أو المدير العام ، كذلك إذا وقع منه اعتداء جسيم علي أحد رؤسائه أثناء العمل أو بسببه . 9- إذا لم يراعي العامل الضوابط الواردة في المواد من (192) إلى (194) من الكتاب الرابع من هذا القانون ."}, {"number": "70", "chapter": "الفصل الثانى", "text": "إذا نشأ نزاع فردى بين صاحب العمل والعامل فى شأن تطبيق أحكام هذا القانون أو أى من القوانين أو اللوائح المنظمة لعلاقات العمل الفردية فلأى منهما أن يطلب من لجنة – تشكل من: ممثل للجهة الإدارية المختصة (مقررا) ، وممثل للمنظمة النقابية ، وممثل لمنظمة أصحاب الأعمال – خلال عشرة أيام من تاريخ النزاع تسويته وديا ، فإذا لم تتم التسوية خلال واحد وعشرين يوما – من تاريخ تقديم الطلب – جاز لأى منهما أن يطلب من الجهة الإدارية المختصة إحالة النزاع إلى المحكمة العمالية المنصوص عليها فى المادة (71) من هذا القانون أو أن يلجأ إليها فى موعد أقصاه خمسة وأربعين يوما من تاريخ انتهاء المدة المحددة للتسوية سواء كان قد تقدم للجنة بطلب التسوية أو لم يتقدم به وإلا سقط حقه فى عرض الأمر على المحكمة ."}, {"number": "مستبدلة بالقانون رقم", "chapter": "الفصل الثانى", "text": "180 لسنة 2008"}, {"number": "71", "chapter": "الفصل الثانى", "text": "تشكل المحكمة العمالية من دائرة أو أكثر من دوائر المحكمة الابتدائية وتختص دون غيرها بالفصل فى كافة المنازعات العمالية الفردية المشار إليها فى المادة (70) من هذا القانون . وتخطر المحكمة ممثلا عن المنظمة النقابية المعنية ، وممثلا عن منظمة أصحاب الأعمال لسماع رأيهما فى النزاع فى أول جلسة ، فإذا تخلف أى منهما عن الحضور استمرت المحكمة فى نظر الدعوى . وعلى المحكمة العمالية أن تفصل – على وجه السرعة وبحكم واجب النفاذ ولو تم استئنافه – فى طلب صاحب العمل بفصل العامل خلال خمسة عشر يوما من تاريخ أول جلسة ، فإذا رفضت الطلب ، قضت باستمرار العامل فى عمله وبإلزام صاحب العمل بأن يؤدى إليه ما لم يصرف له من مستحقات . فإذا لم يقم صاحب العمل بتنفيذ الحكم باستمرار العامل فى عمله أعتبر ذلك فصلا تعسفيا يستوجب التعويض طبقا لنص المادة (122) من هذا القانون . وتقضى المحكمة العمالية – بصفة مستعجلة – وبحكم واجب النفاذ بتعويض مؤقت للعامل يعادل أجره الشامل لمدة اثنى عشر شهرا إذا جاوزت مدة عمله سنة كاملة ، فإن كانت أقل من ذلك كان التعويض المؤقت بقدر أجره الشامل عن مدة عمله إذا طلب منها ذلك . وعلى العامل إعلان صاحب العمل بطلباته النهائية خلال ثلاثين يوما من اليوم التالى لتاريخ صدور الحكم بالتعويض المؤقت إذا لم يكن قد سبق له إبداؤها . وتقضى المحكمة العمالية للعامل بمبلغ التعويض النهائى وفى باقى طلباته بعد أن تخصم المبالغ التى يكون العامل قد استوفاها تنفيذا للحكم الصادر بالتعويض المؤقت . فإذا كان طلب فصل العامل بسبب نشاطه النقابى قضت المحكمة العمالية باستمرار العامل فى عمله إذا طلب ذلك ما لم يثبت صاحب العمل أن طلب الفصل لم يكن بسبب هذا النشاط . ويتبع فيما لم يرد بشأنه نص خاص فى هذا القانون أحكام قانونى المرافعات والإثبات فى المواد المدنية والتجارية."}, {"number": "مستبدلة بالقانون رقم", "chapter": "الفصل الثانى", "text": "180 لسنة 2008"}, {"number": "72", "chapter": "الفصل الثانى", "text": "يتبع فى الطعن على أحكام المحاكم العمالية الأحكام الواردة فى قانون المرافعات المدنية والتجارية ."}, {"number": "مستبدلة بالقانون رقم", "chapter": "الفصل الثانى", "text": "180 لسنة 2008"}, {"number": "73", "chapter": "الفصل الثانى", "text": "إذا تسبب العامل بخطئه وبمناسبة عمله في فقد أو إتلاف مهمات أو آلات أو خامات أو منتجات يملكها صاحب العمل أو كانت في عهدته التزم بأداء قيمة ما فقد أو أتلف . ولصاحب العمل بعد إجراء التحقيق وإخطار العامل أن يبدأ باقتطاع المبلغ المذكور من أجره على ألا يزيد ما يقتطع لهذا الغرض على أجر خمسة أيام في الشهر الواحد . ويجوز للعامل أن يتظلم من تقدير صاحب العمل أمام المحكمة العمالية المشار إليها في المادة (71) من هذا القانون ووفقاً للمدد والإجراءات الواردة بها . فإذا لم يقض لصاحب العمل بالمبلغ الذي قدره للإتلاف أو قضى له بأقل منه وجب عليه رد ما اقتطع دون وجه حق خلال سبعة أيام من تاريخ صدور قرار المحكمة العمالية. ولا يجوز لصاحب العمل أن يستوفي مستحقاته بطريق الاقتطاع وفقاً لحكم هذه المادة إذا بلغ مجموعها أجر شهرين ."}, {"number": "مستبدلة بالقانون رقم", "chapter": "الفصل الثانى", "text": "180 لسنة 2008"}, {"number": "74", "chapter": "الفصل الثانى", "text": "لا تخل الأحكام الواردة بهذا الباب بالضمانات المقررة بقانون النقابات العمالية لأعضاء مجالس إدارة المنظمات النقابية ."}, {"number": "75", "chapter": "الفصل الثانى", "text": "على صاحب العمل قيد الجزاءات المالية التي توقع على العمال في سجل خاص ، مع بيان سبب توقيعها واسم العامل ومقدار أجره ، وأن يفرد لها حساباً خاصاً ، ويكون التصرف فيها طبقاً لما يقرره الوزير المختص بالاتفاق مع الاتحاد العام لنقابات عمال مصر ."}, {"number": "76", "chapter": "الباب السادس", "text": "لا يجوز لصاحب العمل أن يخرج على الشروط المتفق عليها في عقد العمل الفردي أو اتفاقية العمل الجماعية ، أو أن يكلف العامل بعمل غير متفق عليه إلا إذا دعت الضرورة إلى ذلك منعاً لوقوع حادث أو لإصلاح ما نشأ عنه أو في حالة القوة القاهرة ، على أن يكون ذلك بصفة مؤقتة ، وله أن يكلف العامل بعمل غير المتفق عليه إذا كان لا يختلف عنه اختلافاً جوهرياً بشرط عدم المساس بحقوق العامل . ومع ذلك يجوز لصاحب العمل تدريب العامل وتأهيله للقيام بعمل مختلف يتماشى مع التطور التقني في المنشأة ."}, {"number": "77", "chapter": "الباب السادس", "text": "على صاحب العمل أن ينشئ ملفاً لكل عامل يذكر فيه على الأخص ، اسمه ومهنته ودرجة مهارته عند التحاقه بالعمل ومحل إقامته وحالته الاجتماعية وتاريخ بداية خدمته وأجره ، وبيان ما يدخل عليه من تطورات والجزاءات التي وقعت عليه ، وبيان ما حصل عليه من أجازات وتاريخ نهاية خدمته وأسباب ذلك . وعليه أن يودع في الملف محاضر التحقيق وتقارير رؤسائه عن عمله وفقا لما تقرره لائحة المنشأة وأية أوراق أخرى تتعلق بخدمة العامل ، ولا يجوز الإطلاع على هذه البيانات إلا لمن رخص له قانونا بذلك . وعليه أن يحتفظ بملف العامل لمدة سنة على الأقل تبدأ من تاريخ انتهاء علاقة العمل ."}, {"number": "78", "chapter": "الباب السادس", "text": "يلتزم صاحب العمل بنقل العامل من الجهة التي تم التعاقد معه فيها إلى مكان العمل ، كما يلتزم بإعادته إلى تلك الجهة خلال ثلاثة أيام من تاريخ انتهاء عقد العمل لأحد الأسباب المبينة في القانون ، إلا إذا رفض العامل كتابة العودة خلال المدة المذكورة . فإذا لم يقم صاحب العمل بذلك وجب على الجهة الإدارية المختصة إذا تقدم إليها العامل في نهاية المدة المذكورة إعادته إلى الجهة التي تم التعاقد معه فيها على نفقته ، ولهذه الجهة استرداد ما أنفقته بطريق الحجز الإدارى ."}, {"number": "79", "chapter": "الباب السادس", "text": "إذا عهد صاحب العمل إلى صاحب عمل أخر بتأدية عمل من أعماله أو جزء منها وذلك في منطقة عمل واحدة وجب على هذا الأخير أن يسوى بين عماله وعمال صاحب العمل الأصلى في جميع الحقوق ويكون الأخير متضامنا معه في ذلك ."}, {"number": "80", "chapter": "الفصل الأول", "text": "مع عدم الإخلال بأحكام القانون رقم 133 لسنة 1961 فى شأن تنظيم تشغيل العمال فى المنشآت الصناعية ، لا يجوز تشغيل العامل تشغيلاً فعلياً أكثر من ثمان ساعات فى اليوم أو 48 ساعة فى الأسبوع ، ولا تدخل فيها الفترات المخصصة لتناول الطعام والراحة . ويجوز بقرار من الوزير المختص تخفيض الحد الأقصى لساعات العمل لبعض فئات العمال أو فى بعض الصناعات أو الأعمال التى يحددها ."}, {"number": "81", "chapter": "الفصل الأول", "text": "يجب أن تتخلل ساعات العمل فترة أو أكثر لتناول الطعام والراحة لا تقل فى مجموعها عن ساعة ، وأن يراعى فى تحديد هذه الفترة ألا يعمل العامل أكثر من خمس ساعات متصلة . وللوزير المختص أن يحدد بقرار منه الحالات أو الأعمال التى يتحتم- لأسباب فنية أو لظروف التشغيل - استمرار العمل فيها دون فترة راحة ، كما يحدد الأعمال الصعبة أو المرهقة التي يمنح العامل فيها فترات راحة وتحسب من ساعات العمل الفعلية ."}, {"number": "82", "chapter": "الفصل الأول", "text": "يجب تنظيم ساعات العمل وفترات الراحة بحيث لا تتجاوز الفترة بين بداية ساعات العمل ونهايتها أكثر من عشر ساعات فى اليوم الواحد وتحسب فترة الراحة من ساعات التواجد ، إذا كان العامل أثنائها فى مكان العمل . ويستثنى من هذا الحكم العمال المشتغلون فى أعمال متقطعة بطبيعتها والتي يحددها الوزير المختص بقرار منه بحيث لا تزيد مدة تواجدهم على اثنتى عشرة ساعة فى اليوم الواحد ."}, {"number": "83", "chapter": "الفصل الأول", "text": "يجب تنظيم العمل بالمنشأة بحيث يحصل كل عامل على راحة أسبوعية لا تقل عن أربعة وعشرين ساعة كاملة بعد ستة أيام عمل متصلة على الأكثر ، وفى جميع الأحوال تكون الراحة الأسبوعية مدفوعة الأجر ."}, {"number": "84", "chapter": "الفصل الأول", "text": "استثناء من الحكم الوارد فى المادة السابقة ، يجوز فى الأماكن البعيدة عن العمران وفى الأعمال التي تتطلبها طبيعة العمل أو ظروف التشغيل فيها استمرار العمل تجميع الراحة الأسبوعية المستحقة للعامل عن مدة لا تتجاوز ثمانية أسابيع ، وتحدد لائحة تنظيم العمل والجزاءات قواعد الحصول على الراحات الأسبوعية المجمعة ، وتضع المنشآت التي يقل عدد عمالها عن عشرة ، قواعد تنظم الراحات الأسبوعية المجمعة وفقاً للقرارات التي تصدرها المنشأة . ويراعى فى حساب مدة الراحات الأسبوعية المجمعة أن تبدأ من ساعة وصول العمال إلى أقرب موقع بها مواصلات وتنتهى ساعة العودة إليها ."}, {"number": "85", "chapter": "الفصل الأول", "text": "لصاحب العمل عدم التقيد بالأحكام الواردة بالمواد (80 ، 81 ، 82 ، 83 ، 84 ) من هذا القانون إذا كان التشغيل بقصد مواجهة ضرورات عمل غير عادية أو ظروف استثنائية ويشترط فى هذه الحالات إبلاغ الجهة الإدارية المختصة بمبررات التشغيل الإضافى والمدة اللازمة لإتمام العمل والحصول على موافقة كتابية منها . وفى هذه الحالة يستحق العامل بالإضافة إلى أجره الأصلى أجراً عن ساعات التشغيل الإضافية حسبما يتم الاتفاق عليه في عقد العمل الفردى أو الجماعى ، بحيث لا يقل عن الأجر الذي يستحقه العامل مضافاً إلية (35 %) عن ساعات العمل النهارية ، و (70%) عن ساعات العمل الليلية . فإذا وقع التشغيل فى يوم الراحة استحق العامل مثل أجره تعويضاً عن هذا اليوم ، ويمنحه صاحب العمل يوماً آخر عوضاً عنه خلال الأسبوع التالى . وفى جميع الأحوال لا يجوز أن تزيد ساعات العمل الفعلية عن عشرة ساعات فى اليوم الواحد ."}, {"number": "86", "chapter": "الفصل الأول", "text": "على صاحب العمل أن يضع على الأبواب الرئيسية التي يستعملها العمال فى الدخول ، وكذلك فى مكان ظاهر بالمنشأة جدولاً ببيان يوم الراحة الأسبوعية وساعات العمل وفترات الراحة المقررة لكل عامل ، وما يطرأ على هذا الجدول من تعديل ."}, {"number": "87", "chapter": "الفصل الأول", "text": "لا تسرى أحكام المواد ( 80 ، 81 ، 82 ، 84 ) من هذا القانون على : 1- الوكلاء المفوضين عن صاحب العمل . 2- العمال المشتغلين بالأعمال التجهيزية والتكميلية التى يتعين إنجازها قبل أو بعد انتهاء العمل . 3- العمال المخصصين للحراسة والنظافة . وتحدد الأعمال المشار إليها فى البندين (2 ، 3) والحد الأقصى لساعات العمل الفعلية والإضافية فيها بقرار من الوزير المختص ويستحق العمال الوارد ذكرهم فى هذين البندين أجراً إضافياً طبقاً لنص المادة (85) من هذا القانون ."}, {"number": "88", "chapter": "الفصل الثانى", "text": "مع عدم الإخلال بأحكام المواد التالية تسرى على النساء العاملات جميع الأحكام المنظمة لتشغيل العمال دون تمييز بينهم متى تماثلت أوضاع عملهم ."}, {"number": "89", "chapter": "الفصل الثانى", "text": "يصدر الوزير المختص قراراً بتحديد الأحوال والأعمال والمناسبات التي لا يجوز فيها تشغيل النساء فى الفترة ما بين الساعة السابعة مساء والسابعة صباحاً ."}, {"number": "90", "chapter": "الفصل الثانى", "text": "يصدر الوزير المختص قراراً بتحديد الأعمال الضارة بالنساء صحياً أو أخلاقياً ، وكذلك الأعمال التي لا يجوز تشغيل النساء فيها ."}, {"number": "91", "chapter": "الفصل الثانى", "text": "للعاملة التي أمضت عشرة أشهر فى خدمة صاحب عمل أو أكثر الحق فى إجازة وضع مدتها تسعون يوماً بتعويض مساو للأجر الشامل تشمل المدة التي تسبق الوضع والتي تليه ، بشرط أن تقدم شهادة طبية مبيناً بها التاريخ الذي يرجح حصول الوضع فيه . ولا يجوز تشغيل العاملة خلال الخمسة وأربعين يوماً التالية للوضع . ولا تستحق أجازة الوضع لأكثر من مرتين طوال مدة خدمة العاملة ."}, {"number": "92", "chapter": "الفصل الثانى", "text": "يحظر على صاحب العمل فصل العاملة أو إنهاء خدمتها أثناء أجازة الوضع المبينة بالمادة السابقة . ولصاحب العمل حرمانها من التعويض عن أجرها الشامل عن مدة الأجازة أو استرداد ما تم أداؤه إليها منه إذا ثبت اشتغالها خلال الأجازة لدى صاحب عمل آخر ، وذلك مع عدم الإخلال بالمسألة التأديبية ."}, {"number": "93", "chapter": "الفصل الثانى", "text": "يكون للعاملة التي ترضع طفلها فى خلال الأربعة والعشرين شهرا التالية لتاريخ الوضع- فضلاً عن مدة الراحة المقررة - الحق فى فترتين آخرتين للرضاعة لا تقل كل منهما عن نصف ساعة ، وللعاملة الحق فى ضم هاتين الفترتين . وتحسب هاتان الفترتان الإضافيتان من ساعات العمل ولا يترتب عليهما أى تخفيض فى الأجر ."}, {"number": "94", "chapter": "الفصل الثانى", "text": "مع مراعاة حكم الفقرة الثانية من المادة (72) من قانون الطفل الصادر بالقانون رقم 12 لسنة 1996 ، يكون للعاملة في المنشأة التي تستخدم خمسين عاملاً فأكثر الحق في الحصول على أجازة بدون أجر لمدة لا تتجاوز سنتين وذلك لرعاية طفلها ، ولا تستحق هذه الأجازة لأكثر من مرتين طوال مدة خدمتها ."}, {"number": "95", "chapter": "الفصل الثانى", "text": "يجب على صاحب العمل في حالة تشغيله خمس عاملات فأكثر أن يعلق في أمكنة العمل أو تجمع العمال نسخة من نظام تشغيل النساء ."}, {"number": "96", "chapter": "الفصل الثانى", "text": "على صاحب العمل الذي يستخدم مائة عاملة فأكثر في مكان واحد أن ينشئ داراً للحضانة أو يعهد إلى دار للحضانة برعاية أطفال العاملات بالشروط والأوضاع التي تحدد بقرار من الوزير المختص . كما تلتزم المنشآت التي تستخدم أقل من مائة عاملة في منطقة واحدة أن تشترك في تنفيذ الالتزام المنصوص عليه في الفقرة السابقة بالشروط والأوضاع التي تحدد بقرار من الوزير المختص ."}, {"number": "97", "chapter": "الفصل الثانى", "text": "يستثنى من تطبيق أحكام هذا الفصل العاملات في الزراعة البحتة ."}, {"number": "98", "chapter": "الفصل الثالث", "text": "يعتبر طفلاً - في تطبيق أحكام هذا القانون - كل من بلغ الرابعة عشرة سنة أو تجاوز سن إتمام التعليم الأساسى ولم يبلغ ثماني عشرة سنة كاملة . ويلتزم كل صاحب عمل يستخدم طفلاً دون سنة السادسة عشر بمنحة بطاقة تثبت أنه يعمل لديه وتلصق عليها صورة الطفل وتعتمد من مكتب القوى العاملة المختص ."}, {"number": "99", "chapter": "الفصل الثالث", "text": "يحظر تشغيل الأطفال من الإناث والذكور قبل بلوغهم سن إتمام التعليم الأساسى ، أو أربعة عشرة سنة أيهما أكثر ، ومع ذلك يجوز تدريبهم متى بلغت سنهم اثنتى عشرة سنة ."}, {"number": "100", "chapter": "الفصل الثالث", "text": "يصدر الوزير المختص قرارا بتحديد نظام تشغيل الأطفال والظروف والشروط والأحوال التي يتم فيها التشغيل ، وكذلك الأعمال والمهن والصناعات التي يحظر تشغيلهم فيها وفقاً لمراحل السن المختلفة ."}, {"number": "101", "chapter": "الفصل الثالث", "text": "يحظر تشغيل الطفل أكثر من ست ساعات يومياً ، ويجب أن تتخلل ساعات العمل فترة أو أكثر لتناول الطعام والراحة لا تقل في مجموعها عن ساعة واحدة ، وتحدد هذه الفترة أو الفترات بحيث لا يشتغل الطفل أكثر من أربع ساعات متصلة . ويحظر تشغيل الطفل ساعات عمل إضافية أو تشغيله في أيام الراحة الأسبوعية والعطلات الرسمية . وفي جميع الأحوال يحظر تشغيل الطفل فيما بين الساعة السابعة مساءاً والسابعة صباحاً ."}, {"number": "102", "chapter": "الفصل الثالث", "text": "على صاحب العمل الذي يقوم بتشغيل طفل أو أكثر: (أ) أن يعلق فى مكان ظاهر فى محل العمل نسخة تحتوى على الأحكام التى يتضمنها هذا الفصل . (ب) أن يحرر كشفاً موضحاً به ساعات العمل وفترات الراحة معتمداً من الجهة الإدارية المختصة . (ج) أن يبلغ الجهة الإدارية المختصة بأسماء الأطفال العاملين لديه والأعمال المكلفين بها وأسماء الأشخاص المنوط بهم مراقبة أعمالهم ."}, {"number": "103", "chapter": "الفصل الثالث", "text": "لا تسرى أحكام هذا الفصل على الأطفال الذين يعملون فى أعمال الزراعة البحتة ."}, {"number": "104", "chapter": "الباب السابع", "text": "ينتهى عقد العمل محدد المدة بانقضاء مدته . فإذا ابرم العقد لمدة تزيد على خمس سنوات ، جاز للعامل إنهاؤه دون تعويض- عند انقضاء خمس سنوات - وذلك بعد إخطار صاحب العمل قبل الإنهاء بثلاثة أشهر . وتسري أحكام الفقرة السابقة على حالات إنهاء العامل للعقد بعد انقضاء المدة المذكورة ."}, {"number": "105", "chapter": "الباب السابع", "text": "مع مراعاة أحكام المادة (106) من هذا القانون إذا انقضت مدة عقد العمل محدد المدة واستمر طرفاه فى تنفيذه ، أعتبر ذلك منهما تجديداً للعقد لمدة غير محددة . ولا يسرى ذلك على عقود عمل الأجانب ."}, {"number": "106", "chapter": "الباب السابع", "text": "إذا انتهى عقد العمل المحدد المدة بانقضاء مدته ، جاز تجديده باتفاق صريح بين طرفيه لمدة أو لمدد أخرى . فإذا زادت مدد العقد الأصلية والمجددة على خمس سنوات ، جاز للعامل إنهاؤه وفقاً لأحكام المادة (104) من هذا القانون ."}, {"number": "107", "chapter": "الباب السابع", "text": "إذا ابرم عقد العمل لإنجاز عمل معين ، انتهى العقد بإنجاز هذا العمل ، فإذا استغرق هذا الإنجاز مدة تزيد على خمس سنوات ، لا يجوز للعامل إنهاء العقد قبل تمام إنجاز العمل ."}, {"number": "108", "chapter": "الباب السابع", "text": "إذا انتهى عقد العمل المبرم لإنجاز عمل معين واستمر طرفاه في تنفيذ العقد بعد إنجاز العمل ، اعتبر ذلك تجديداً منهما للعقد لمدة غير محددة ."}, {"number": "109", "chapter": "الباب السابع", "text": "إذا انتهى عقد العمل المبرم لعمل معين بإنجازه ، جاز تجديده باتفاق صريح بين طرفيه وذلك لعمل أو أعمال أخرى مماثلة . فإذا زادت مدة إنجاز العمل الأصلى والأعمال التى جدد العقد لها على خمس سنوات ، لا يجوز للعامل إنهاء العقد قبل تمام إنجاز هذه الأعمال ."}, {"number": "110", "chapter": "الباب السابع", "text": "مع عدم الإخلال بحكم المادة (198) من هذا القانون ومراعاة أحكام المواد التالية ، إذا كان عقد العمل غير محدد المدة ، جاز لكل من طرفيه إنهاؤه بشرط أن يخطر الطرف الآخر كتابة قبل الإنهاء . ولا يجوز لصاحب العمل أن ينهى هذا العقد إلا في حدود ما ورد في المادة (69) من هذا القانون أو ثبوت عدم كفاءة العامل طبقا لما تنص عليه اللوائح المعتمدة . كما يجب أن يستند العامل فى الإنهاء إلى مبرر مشروع وكاف يتعلق بظروفة الصحية أو الاجتماعية أو الاقتصادية . ويراعي في جميع الأحوال أن يتم الإنهاء في وقت مناسب لظروف العمل ."}, {"number": "111", "chapter": "الباب السابع", "text": "يجب أن يتم الإخطار قبل الإنهاء بشهرين إذا لم تتجاوز مدة الخدمة المتصلة للعامل لدى صاحب العمل عشر سنوات ، وقبل الإنهاء بثلاث أشهر إذا زادت هذه المدة على عشر سنوات ."}, {"number": "112", "chapter": "الباب السابع", "text": "لا يجوز تعليق الإخطار بالإنهاء على شرط واقف أو فاسخ . ويبدأ سريان مهلة الإخطار من تاريخ تسلمه ، وتحتسب مدة خدمة العامل من تاريخ تسلمه العمل وحتى تاريخ انتهاء مهلة الإخطار ."}, {"number": "113", "chapter": "الباب السابع", "text": "لا يجوز توجيه الإخطار للعامل خلال إجازته ولا تحتسب مهلة الإخطار إلا من اليوم التالي لانتهاء الإجازة . وإذا حصل العامل على إجازة مرضية خلال مهلة الإخطار يوقف سريان هذه المهلة ولا يبدأ سريانها من جديد إلا من اليوم التالى لانتهاء تلك الإجازة ."}, {"number": "114", "chapter": "الباب السابع", "text": "يظل عقد العمل قائماً طوال مهلة الإخطار ويلتزم طرفاه بتنفيذ جميع الالتزامات الناشئة عنه ، وينتهى العقد بانقضاء هذه المهلة ."}, {"number": "115", "chapter": "الباب السابع", "text": "لا يجوز الاتفاق على الإعفاء من شرط الإخطار أو تخفيض مدته ، ولكن يجوز الاتفاق على زيادة هذه المدة . ويجوز لصاحب العمل إعفاء العامل من مراعاة مهلة الإخطار كلها أو بعضها في حالة إنهاء العقد من جانب العامل ."}, {"number": "116", "chapter": "الباب السابع", "text": "إذا كان الإخطار بالإنهاء من جانب صاحب العمل ، يحق للعامل أن يتغيب يوماً كاملاً في الأسبوع أو ثمانى ساعات أثناء الأسبوع ، وذلك للبحث عن عمل آخر مع استحقاقه لأجره عن يوم أو ساعات الغياب . ويكون للعامل تحديد يوم الغياب أو ساعاته بشرط أن يخطر صاحب العمل بذلك في اليوم السابق للغياب على الأقل ."}, {"number": "117", "chapter": "الباب السابع", "text": "لصاحب العمل أن يعفى العامل من العمل أثناء مهلة الإخطار ، مع احتساب مدة خدمة العامل مستمرة إلى حين انتهاء تلك المهلة ، مع ما يترتب على ذلك من آثار وبخاصة استحقاق العامل أجره عن مهلة الإخطار ."}, {"number": "118", "chapter": "الباب السابع", "text": "إذا أنهى صاحب العمل عقد العمل دون إخطار أو قبل انقضاء مهلة الإخطار التزم بأن يؤدى للعامل مبلغاً يعادل أجره عن مدة المهلة أو الجزء الباقي منها . وفي هذه الحالة تحسب مدة المهلة أو الجزء الباقى منها ضمن مدة خدمة العامل ، ويستمر صاحب العمل في تحمل الأعباء والالتزامات المترتبة على ذلك . أما إذا كان الإنهاء صادراً من جانب العامل فإن العقد ينتهى من وقت تركه العمل ."}, {"number": "119", "chapter": "الباب السابع", "text": "لا يعتد باستقالة العامل إلا إذا كانت مكتوبة ، وللعامل المستقيل أن يعدل عن استقالته كتابة خلال أسبوع من تاريخ إخطار صاحب العمل للعامل بقبول الاستقالة ، وفي هذه الحالة تعتبر الاستقالة كأن لم تكن ."}, {"number": "120", "chapter": "الباب السابع", "text": "لا تعتبر من المبررات المشروعة والكافية للإنهاء الأسباب الآتية: (أ) اللون أو الجنس أو الحالة الإجتماعية أو المسئوليات العائلية أو الحمل أو الدين أو الرأى السياسى . (ب) إنتساب العامل إلي منظمة نقابية أو مشاركته في نشاط نقابى في نطاق ما تحدده القوانين . (ج) ممارسة صفة ممثل العمال أو سبق ممارسة هذه الصفة أو السعي إلي تمثيل العمال . (د) تقديم شكوى أو إقامة دعوى ضد صاحب العمل أو مشاركة فى ذلك تظلماً من إخلال بالقوانين أو اللوائح أو عقود العمل . (هـ) توقيع الحجز علي مستحقات العامل تحت يد صاحب العمل . (و) استخدام العامل لحقه في الأجازات ."}, {"number": "121", "chapter": "الباب السابع", "text": "للعامل إنهاء العقد إذا أخل صاحب العمل بإلتزام من إلتزاماته الجوهرية الناشئة عن القانون أو عقد العمل الفردى أو الجماعى أو لائحة النظام الأساسى للمنشأة أو إذا وقع علي العامل أو أحد ذويه إعتداء من صاحب العمل أو ممن يمثله . ويعتبر الإنهاء في هذه الحالات بمثابة إنهاء للعقد من جانب صاحب العمل بغير مبرر مشروع ."}, {"number": "122", "chapter": "الباب السابع", "text": "إذا أنهى أحد الطرفين العقد دون مبرر مشروع وكاف ، إلتزم بأن يعوض الطرف الأخر عن الضرر الذي يصيبه من جراء هذا الإنهاء . فإذا كان الإنهاء بدون مبرر صادراً من جانب صاحب العمل ، للعامل أن يلجأ إلى المحكمة العمالية المشار إليها في المادة (71) من هذا القانون بطلب التعويض ، ولا يجوز أن يقل التعويض الذى تقرره المحكمة العمالية عن أجر شهرين من الأجر الشامل عن كل سنة من سنوات الخدمة . ولا يخل ذلك بحق العامل في باقى استحقاقاته المقررة قانوناً ."}, {"number": "123", "chapter": "الباب السابع", "text": "ينتهى عقد العمل بوفاة العامل حقيقة أو حكماً طبقاً للقواعد القانونية المقررة . ولا ينتهى عقد العمل بوفاة صاحب العمل إلا إذا كان قد أبرم لاعتبارات تتعلق بشخص صاحب العمل أو بنشاطه الذى ينقطع بوفاته . وإذا توفى العامل وهو في الخدمة يصرف صاحب العمل لأسرته ما يعادل أجر شهرين كاملين لمواجهة نفقات الجنازة بحد أدنى قدرة مائتان وخمسون جنيهاً ، كما يصرف منحة تعادل أجر العامل كاملاً عن الشهر الذى توفى فيه والشهرين التاليين له طبقاً لقواعد قوانين التأمين الاجتماعى . ويلتزم صاحب العمل بنفقات تجهيز ونقل الجثمان إلى الجهة التى استقدم العامل منها أو الجهة التي تطلب أسرته نقله إليها ."}, {"number": "124", "chapter": "الباب السابع", "text": "ينتهى عقد العمل بعجز العامل عن تأدية عمله عجزاً كلياً أياً كان سبب هذا العجز . فإذا كان عجز العامل عجزاً جزئياً فلا تنتهى علاقة العمل بهذا العجز إلا إذا ثبت عدم وجود عمل آخر لدى صاحب العمل يستطيع العامل أن يقوم به على وجه مرض ، ويثبت وجود أو عدم وجود العمل الآخر وفقاً لأحكام قانون التأمين الاجتماعى . وإذا ثبت وجود هذا العمل الآخر كان على صاحب العمل بناء على طلب العامل أن ينقله إلى ذلك العمل مع عدم الإخلال بأحكام قانون التأمين الاجتماعى ."}, {"number": "125", "chapter": "الباب السابع", "text": "لا يجوز تحديد سن للتقاعد تقل عن ستين سنة . ويجوز لصاحب العمل إنهاء عقد العامل إذا بلغ سن الستين ، ما لم يكن العقد محدد المدة وكانت مدته تمتد إلى ما بعد بلوغه هذه السن ، ففى هذه الحالة لا ينتهى العقد إلا بانقضاء مدته . وفي جميع الأحوال يجب عدم الإخلال بأحكام قانون التأمين الاجتماعي فيما يتعلق بسن استحقاق المعاش وبحق العامل في الاستمرار في العمل بعد بلوغه هذه السن استكمالاً للمدة الموجبة لاستحقاق المعاش ."}, {"number": "126", "chapter": "الباب السابع", "text": "يستحق العامل عن مدة عمله بعد سن الستين مكافأة بواقع أجر نصف شهر عن كل سنة من السنوات الخمس الأولى ، وأجر شهر عن كل سنة من السنوات التالية لها ، وذلك إذا لم تكن له حقوق عن هذه المدة وفقاً لأحكام تأمين الشيخوخة والعجز والوفاة المنصوص عليها في قانون التأمين الاجتماعى . وتستحق المكافأة المنصوص عليها في الفقرة السابقة عن سنوات الخدمة السابقة على سنة الثامنة عشر وذلك للمتدرج والعامل عند بلوغ هذه السن ، وتحسب المكافأة على أساس آخر ما كان يتقاضاه ."}, {"number": "127", "chapter": "الباب السابع", "text": "يحظر على صاحب العمل إنهاء عقد العمل لمرض العامل إلا إذا استنفد العامل أجازاته المرضية وفقاً لما يحدده قانون التأمين الاجتماعي ، بالإضافة إلى متجمد أجازاته السنوية المستحقة له . وعلى صاحب العمل أن يخطر العامل برغبته في إنهاء العقد قبل مضى خمسة عشر يوماً من تاريخ استنفاد العامل لأجازاته . فإذا شفى العامل قبل تمام الإخطار امتنع على صاحب العمل إنهاء العقد لمرض العامل ."}, {"number": "128", "chapter": "الباب السابع", "text": "للعاملة أن تنهى عقد العمل سواء كان محدد المدة أو غير محدد المدة بسبب زواجها أو حملها أو إنجابها دون أن يؤثر ذلك على الحقوق المقررة لها وفقا لأحكام هذا القانون أو لأحكام قانون التأمين الاجتماعى . وعلى العاملة التي ترغب في إنهاء العقد للأسباب المبينة في الفقرة السابقة أن تخطر صاحب العمل كتابة برغبتها في ذلك خلال ثلاثة أشهر من تاريخ إبرام عقد الزواج أو ثبوت الحمل أو من تاريخ الوضع بحسب الأحوال ."}, {"number": "129", "chapter": "الباب السابع", "text": "لصاحب العمل أن ينهي عقد العمل ولو كان محدد المدة أو مبرماً لإنجاز عمل معين إذا حكم على العامل نهائياً بعقوبة جنائية أو بعقوبة مقيدة للحرية في جريمة ماسة بالشرف أو الأمانة أو الآداب العامة ، وذلك ما لم تأمر المحكمة بوقف تنفيذ العقوبة ."}, {"number": "130", "chapter": "الباب السابع", "text": "يلتزم صاحب العمل أن يعطى العامل دون مقابل عند انتهاء عقده وبناء على طلبه شهادة يبين فيها تاريخ التحاقه بالخدمة وتاريخ انتهائها ، ونوع العمل الذي كان يؤديه والمزايا التي كان يحصل عليها . وللعامل أن يحصل من صاحب العمل دون مقابل على شهادة بتحديد خبرته وكفاءته المهنية وذلك أثناء سريان العقد وفي نهايته . ويجوز بناء على طلب العامل تضمين الشهادة مقدار الأجر الذي كان يتقاضاه وسبب إنهاء علاقة العمل . ويلتزم صاحب العمل بأن يرد للعامل عند انتهاء عقده ما يكون قد أودعه لديه من أوراق أو شهادات أو أدوات فور طلبها ."}, {"number": "131", "chapter": "الكتاب الثالث", "text": "يقصد فى تطبيق أحكام هذا الكتاب بالمصطلحات الآتية المعاني المبينة قرين كل منها: بالتوجيه المهنى : مساعدة الفرد فى اختيار المهنة أو المسار المهنى الأكثر ملاءمة لقدراته واستعداده وميوله فى ضوء الدراسات المستمرة لسوق العمل والمهن المطلوبة ومقوماتها . بالتدريب المهنى: الوسائل التي من شأنها تمكين الفرد من اكتساب وتنمية المعارف والمهارات والقدرات اللازمة لإعداده للعمل المناسب ."}, {"number": "132", "chapter": "الباب الأول", "text": "يشكل المجلس الأعلى لتنمية الموارد البشرية ويصدر بتحديد اختصاصه ونظام العمل به ، قرار من رئيس الجمهورية ، ويتولى رسم السياسة القومية لتخطيط التنمية البشرية ووضع برنامج قومي لتنميتها واستخدامها الاستخدام الأمثل بالتنسيق مع الوزارات والجهات المختصة ."}, {"number": "133", "chapter": "الباب الأول", "text": "ينشأ صندوق لتمويل التدريب والتأهيل تكون له الشخصية الاعتبارية العامة ، يتبع الوزير المختص ، وذلك لتمويل إنشاء وتطوير وتحديث مراكز وبرامج التدريب التى تستهدف المواءمة بين احتياجات سوق العمل المحلى والخاص . ويختص الصندوق بوضع الشروط والقواعد التي تتبع لبرامج ومدد التدريب المهنى الدراسية والنظرية ، ونظم الاختبارات والشهادات التي تصدر فى هذا الشأن . ويصدر رئيس مجلس الوزراء قراراً بتشكيل مجلس إدارة الصندوق برئاسة الوزير المختص يحدد نظام العمل به وفروعه فى المحافظات ولائحته التنفيذية ونظام تحصيل موارده والنظام المحاسبى الواجب إتباعه ونظام الرقابة على أمواله ."}, {"number": "134", "chapter": "الباب الأول", "text": "تتكون موارد الصندوق المشار إليه فى المادة السابقة من: 1- 1% من صافى أرباح المنشآت الخاضعة لأحكام هذا القانون والتى يزيد عدد العاملين بها على عشرة عمال . 2- ما تخصصه له الدولة من موارد . 3- الإعانات والتبرعات والهبات التي يقبلها مجلس إدارة الصندوق طبقاً للقواعد التي تحددها اللائحة التنفيذية للصندوق . 4- عائد استثمار أموال الصندوق ، طبقاً للقواعد التي تحددها اللائحة التنفيذية للصندوق . ويكون للصندوق حساب خاص لدى أحد البنوك التجارية المعتمدة لدى البنك المركزى وترحل أمواله من سنة مالية إلى أخرى . ويعد الصندوق سنوياً القوائم الدالة على المركز المالى وتخضع أمواله لرقابة الجهاز المركزى للمحاسبات ."}, {"number": "135", "chapter": "الباب الثانى", "text": "لا يجوز لأية جهة مزاولة عمليات التدريب المهني إلا إذا كانت متخذة شكل شركة من شركات المساهمة أو التوصية بالأسهم أو الشركات ذات المسئولية المحدودة ، ويحدد المجلس الأعلى لتنمية الموارد البشرية المنصوص عليه فى المادة (132) من هذا القانون الحد الأدنى لرأسمال كل من هذه الشركات بحسب نوع النشاط الذي تمارس فيه عملية التدريب . ويستثنى من أحكام الفقرة السابقة: 1- الجهات والمنظمات النقابية والجمعيات والمؤسسات الأهلية المنشأة وفقاً للقانون رقم 84 لسنة 2002 والتى تزاول عمليات التدريب المهني وقت صدور هذا القانون . 2- الجهات التى تنشئها وحدات الجهاز الإدارى للدولة والهيئات العامة ووحدات الإدارة المحلية . 3- الجهات التى تزاول عمليات التأهيل والتدريب المهني للمعوقين . 4- المنشآت التى تتولى تدريب عمالها ."}, {"number": "136", "chapter": "الباب الثانى", "text": "يشترط لمزاولة عمليات التدريب المهني الحصول على ترخيص بذلك من الوزارة المختصة باستثناء الجهات المنصوص عليها فى البنود (2 ، 3 ، 4) من الفقرة الثانية من المادة السابقة . ويصدر الوزير المختص قراراً بتحديد شروط وقواعد وإجراءات منح الترخيص وقيده فى السجل الخاص . ويعد بالوزارة المذكورة سجل لقيد الجهات التى يتم الترخيص لها بمزاولة عمليات التدريب المهني . وتلتزم الجهات التى تزاول عمليات التدريب المهني وقت صدور هذا القانون بالحصول على الترخيص المشار إليه خلال سنة من تاريخ العمل بهذا القانون ، ويلغى الترخيص فى حالة الإخلال بأى شرط من شروطه ."}, {"number": "137", "chapter": "الباب الثالث", "text": "تلتزم الجهات المرخص لها بالتدريب المهنى بعرض البرامج التدريبية التي تضعها على الأجهزة المعنية بالوزارة المختصة لاعتمادها مراعية فى ذلك: 1- الشروط التي يجب توافرها فى المتدربين للالتحاق بالبرامج ومصروفات التدريب . 2- مدى كفاية العمليات التدريبية من حيث موضوعات ومجالات التدريب وعدد الساعات المخصصة لها . 3- مستويات ونوعيات المدربين . 4- مستوى المهارة التي يكتسبها المتدرب بعد الانتهاء من البرنامج . 5- أية شروط أخرى تضعها الوزارة المختصة . ويتم اعتماد البرامج المقدمة خلال ستين يوماُ من تاريخ تقديمها ، ويعتبر فوات هذه المدة دون إخطار اعتماداً لهذه البرامج ."}, {"number": "138", "chapter": "الباب الثالث", "text": "يشترط فى المدربين الذين يزاولون أعمال التدريب المهني أن يرخص لهم بذلك من الوزارة المختصة . ويصدر الوزير المختص قراراً بتحديد شروط وقواعد وإجراءات منح الترخيص ، وحالات إلغاءه . ويعد بالوزارة المختصة سجل لقيد المدربين المرخص لهم ، يتم التأشير فيه بحالات إلغاء التراخيص ."}, {"number": "139", "chapter": "الباب الرابع", "text": "تلتزم الجهة التي تزاول عمليات التدريب المهنى أن تمنح المتدرب شهادة تفيد اجتيازه البرنامج التدريبى الذي عقدته وتبين المستوى الذي بلغه . ويحدد بقرار من الوزير المختص البيانات الأخرى التي تدون فى هذه الشهادة وكذلك الأحكام الخاصة بقياس مستوى المهارة والجهات التي تختص بتحديد هذا المستوى ، والحرف التي تخضع لهذا القياس ، وكيفية إجرائه وشروط التقدم له والمكان الذى يجرى فيه بالنسبة لكل حرفة ، والشهادات التى تمنحها الجهات التي تتولى هذا الإجراء ، ودرجات المهارة التي تقدرها وجميع البيانات التي يجب إثباتها فى تلك الشهادات مع بيان الرسم المقرر عنها بما لا يجاوز أربعين جنيهاً وحالات الإعفاء من هذا الرسم ."}, {"number": "140", "chapter": "الباب الرابع", "text": "على كل من يرغب فى مزاولة حرفة من الحرف الواردة بقرار من الوزير المختص المشار إليها فى المادة السابقة ، التقدم للجهة الإدارية المختصة بطلب الحصول على ترخيص مزاولة الحرفة . ويحظر على صاحب العمل استخدام عامل فى إحدى الحرف المبينة بالقرار الوزارى المشار إليه بالفقرة السابقة إلا إذا كان العامل حاصلاً على الترخيص المذكور . ويحدد بقرار من الوزير المختص ، بعد أخذ رأى التنظيم النقابى ، شروط وقواعد وإجراءات منح الترخيص والرسم المقرر له بما لا يجاوز أربعين جنيهاً ، وحالات الإعفاء منه ."}, {"number": "141", "chapter": "الباب الخامس", "text": "يعتبر متدرجاً كل من يلتحق لدى صاحب عمل بقصد تعلم مهنة أو صناعة . ويصدر الوزير المختص قراراً بالقواعد والإجراءات المنظمة للتدرج المهنى ."}, {"number": "142", "chapter": "الباب الخامس", "text": "يجب أن يكون اتفاق التدرج مكتوباً وتحدد فيه مدة تعلم المهنة أو الصنعة ومراحلها المتتابعة والمكافأة فى كل مرحلة بصورة تصاعدية على ألا تقل فى المرحلة الأخيرة عن الحد الأدنى للأجر المحدد لفئة العمال فى المهنة أو الصنعة التى يتدرج فيها ."}, {"number": "143", "chapter": "الباب الخامس", "text": "لصاحب العمل أن ينهى اتفاق التدرج إذا ثبت لديه عدم صلاحية المتدرج أو عدم استعداده لتعلم المهنة أو الصنعة بصورة حسنة ، كما يجوز للمتدرج أن ينهى الاتفاق . ويشترط أن يخطر الطرف الراغب فى إنهاء الاتفاق الطرف الآخر بذلك قبل ثلاثة أيام على الأقل ."}, {"number": "144", "chapter": "الباب الخامس", "text": "تسرى على المتدرجين الأحكام الخاصة بالأجازات وساعات العمل وفترات الراحة المنصوص عليه فى المواد من (47) إلى (55) ومن (80) إلى (87) من هذا القانون ."}, {"number": "145", "chapter": "الباب الأول", "text": "يشكل بقرار من رئيس مجلس الوزراء مجلس استشارى للعمل يضم للعمل فى عضويته ممثلين للجهات المعنية وعدداً من ذوى الخبرة وممثلين لكل من منظمات أصحاب الأعمال ومنظمات العمال تختارهم منظماتهم بالتساوى بينهم ، ويحدد القرار رئيس المجلس ونظام العمل به ويتولى المجلس على وجه الخصوص ما يلي: أ- إبداء الرأى فى مشروعات القوانين المتعلقة بعلاقات العمل . ب- إبداء الرأى فى اتفاقيات العمل الدولية قبل التوقيع عليها . ج- دراسة الموضوعات ذات الصلة بالعلاقات المهنية والإنتاجية على المستوى القومى . د- اقتراح وسائل توثيق التعاون بين منظمات العمال ومنظمات أصحاب الأعمال . هـ - اقتراح الحلول المناسبة لاتقاء منازعات العمل الجماعية على المستوى القومى وعلى الأخص فى الأزمات الاقتصادية التي تؤدى إلى توقف بعض المشروعات عن العمل كلياُ أو جزئياُ . و- إبداء الرأي في الموضوعات التي تعرضها عليه الوزارة المختصة ."}, {"number": "146", "chapter": "الباب الثانى", "text": "المفاوضة الجماعية هى الحوار والمناقشات التى تجرى بين المنظمات النقابية العمالية وبين أصحاب الأعمال أو منظماتهم ، من أجل: أ - تحسين شروط وظروف العمل وأحكام الاستخدام . ب - التعاون بين طرفى العمل لتحقيق التنمية الاجتماعية لعمال المنشأة . ج - تسوية المنازعات بين العمال وأصحاب الأعمال ."}, {"number": "147", "chapter": "الباب الثانى", "text": "تكون المفاوضة الجماعية على مستوى المنشأة أو فرع النشاط أو المهنة أو الصناعة كما تكون على المستوى الإقليمي أو القومي ."}, {"number": "148", "chapter": "الباب الثانى", "text": "يتم التفاوض فى المنشآت التى تستخدم خمسين عاملاً فأكثر بين ممثلين عن اللجنة النقابية بالمنشأة والنقابة العامة وبين صاحب العمل . فإذا لم توجد لجنة نقابية بالمنشأة يكون التفاوض بين صاحب العمل وخمسة عمال تختارهم النقابة العامة المعنية على أن يكون من بينهم ثلاثة على الأقل من عمال المنشأة . وبالنسبة للمنشآت التى تستخدم أقل من خمسين عاملاً يتم التفاوض بين ممثلين عن النقابة العامة المعنية ، وبين ممثلين عن منظمة أصحاب الأعمال المعنية أو عن صاحب العمل ، ويعتبر ممثلو كل طرف مفوضين قانوناُ فى إجراءا التفاوض وإبرام ما يسفر عنة من اتفاق . فإذا رفض أحد الطرفين البدء فى إجراءات المفاوضة الجماعية جاز للطرف الآخر أن يطلب من الجهة الإدارية المختصة تحريك إجراءات التفاوض بإخطار منظمة أصحاب الأعمال أو المنظمة النقابية للعمال بحسب الأحوال لمباشرة التفاوض الجماعى نيابة عن الطرف الرافض ، وتعتبر المنظمة المختصة فى هذه الحالة مفوضة قانوناُ فى التفاوض وتوقيع الاتفاق الجماعى ."}, {"number": "149", "chapter": "الباب الثانى", "text": "يلتزم صاحب العمل بتقديم ما يطلبه ممثلو التنظيم النقابي فى المفاوضات الجماعية من بيانات ومعلومات خاصة بالمنشأة . ولصاحب العمل أو ممثلى التنظيم النقابى طلب هذه البيانات من منظماتهم بحسب الأحوال . ويلتزم الاتحاد العام لنقابات عمال مصر ، ومنظمات أصحاب الأعمال بتقديم ما يلزم لحسن سير المفاوضات الجماعية من البيانات والمعلومات الخاصة بفرع النشاط أو المهنة أو الصناعة ، وللاتحاد العام والمنظمات المشار إليها طلب هذه البيانات والمعلومات من الجهات المعنية . ويراعى فى جميع الأحوال أن تكون البيانات والمعلومات المطلوبة جوهرية ولازمة للسير فى المفاوضة ."}, {"number": "150", "chapter": "الباب الثانى", "text": "يحظر على صاحب العمل أثناء المفاوضة اتخاذ إجراءات أو إصدار قرارات تتعلق بالموضوعات المطروحة للتفاوض ، إلا عند قيام حالة الضرورة والاستعجال ويشترط أن يكون الإجراء أو القرار فى هذه الحالة مؤقتاً ."}, {"number": "151", "chapter": "الباب الثانى", "text": "يدون الاتفاق الذى تسفر عنه المفاوضة فى اتفاقية جماعية طبقاً للشروط والقواعد الخاصة باتفاقيات العمل الجماعية الواردة فى هذا القانون . فإذا لم تسفر المفاوضة عن اتفاق كان لأي من الطرفين أن يلجأ إلى الجهة الإدارية المختصة لمحاولة التوفيق بينهما ومساعدتهما للوصول إلى اتفاق ."}, {"number": "152", "chapter": "الباب الثالث", "text": "اتفاقية العمل الجماعية هى اتفاق ينظم شروط وظروف العمل وأحكام التشغيل ، ويبرم بين منظمة أو أكثر من المنظمات النقابية العمالية وبين صاحب العمل أو مجموعة من أصحاب الأعمال أو منظمة أو أكثر من منظماتهم ."}, {"number": "153", "chapter": "الباب الثالث", "text": "يجب أن تكون الاتفاقية الجماعية مكتوبة باللغة العربية ، وأن تعرض خلال خمسة عشر يوما من تاريخ توقيعها على مجلس إدارة النقابة العامة أو الاتحاد العام لنقابات عمال مصر على حسب الأحوال المقررة فى قانون النقابات العمالية ، وتكون الموافقة عليها من أيهما بالأغلبية المطلقة لأعضاء مجلس الإدارة وذلك خلال مدة لا تجاوز ثلاثين يوماً من تاريخ توقيع الاتفاقية . ويترتب على تخلف أى شرط من الشروط السابقة بطلان الاتفاقية ."}, {"number": "154", "chapter": "الباب الثالث", "text": "يقع باطلا كل حكم يرد فى الاتفاقية الجماعية يكون مخالفاً لأحكام القانون أو النظام العام أو الآداب العامة . وفى حالة تعارض حكم فى عقد العمل الفردي مع حكم مقابل فى الاتفاقية الجماعية يسرى الحكم الذي يحقق فائدة أكثر للعامل دون غيره ."}, {"number": "155", "chapter": "الباب الثالث", "text": "يكون إبرام الاتفاقية الجماعية لمدة محددة لا تزيد على ثلاث سنوات أو للمدة اللازمة لتنفيذ مشروع معين ، فإذا زادت المدة فى الحالة الأخيرة على ثلاث سنوات تعين على طرفي الاتفاقية التفاوض لتجديدها كل ثلاث سنوات فى ضوء ما يكون قد استجد من ظروف اقتصادية واجتماعية . ويتبع فى شأن التجديد الإجراءات الواردة بالمادة (156) من هذا القانون ."}, {"number": "156", "chapter": "الباب الثالث", "text": "يتعين على طرفى الاتفاقية سلوك طريق المفاوضة الجماعية لتجديدها قبل انتهاء مدتها بثلاثة أشهر ، فإذا انقضت المدة الأخيرة دون الإتفاق على التجديد أمتد العمل بالاتفاقية مدة ثلاثة أشهر ويستمر التفاوض لتجديدها ، فإذا انقضى شهران دون التوصل إلى اتفاق كان لأى من طرفى الاتفاقية عرض الأمر على الجهة الإدارية المختصة لاتخاذ ما يلزم نحو إتباع إجراءات الوساطة وفقاً لأحكام المادة (170) من هذا القانون ."}, {"number": "157", "chapter": "الباب الثالث", "text": "يلتزم صاحب العمل بأن يضع فى مكان ظاهر فى محل العمل الاتفاقية الجماعية متضمنة نصوصها والموقعين عليها وتاريخ إيداعها لدى الجهة الإدارية المختصة ."}, {"number": "158", "chapter": "الباب الثالث", "text": "تكون الاتفاقية الجماعية نافذة وملزمة لطرفيها بعد إيداعها لدى الجهة الإدارية المختصة ونشر هذا الإيداع بالوقائع المصرية مشتملاً على ملخص لأحكام الاتفاقية . وتتولى الجهة الإدارية المختصة قيد الاتفاقية خلال ثلاثين يوماً من تاريخ إيداعها لديها ونشر القيد وفقاً لأحكام الفقرة الأولى . ولها خلال المدة المذكورة الاعتراض على الاتفاقية ورفض قيدها وإخطار طرفى الاتفاقية بالاعتراض والرفض ، وأسبابه وذلك بكتاب موصى عليه ومصحوب بعلم الوصول . فإذا انقضت المدة المذكورة ولم تقم الجهة الإدارية بالقيد والنشر أو الاعتراض وجب عليها إجراء القيد والنشر وفقاُ للأحكام السابقة ."}, {"number": "159", "chapter": "الباب الثالث", "text": "إذا رفضت الجهة الإدارية المختصة قيد الاتفاقية وفق أحكام المادة السابقة جاز لكل من طرفى الاتفاقية اللجوء إلى المحكمة الابتدائية التى يقع بدائرتها محل العمل بطلب القيد وفق الإجراءات المعتادة لرفع الدعوى ، وذلك خلال ثلاثين يوماً من تاريخ الإخطار بالرفض . فإذا قضت المحكمة بقيد الاتفاقية وجب على الجهة الإدارية المختصة إجراء القيد فى السجل الخاص ونشر ملخص الاتفاقية فى الوقائع المصرية بلا مصروفات ."}, {"number": "160", "chapter": "الباب الثالث", "text": "للمنظمات النقابية وأصحاب الأعمال ومنظماتهم من غير طرفي الاتفاقية الجماعية الانضمام إلى الاتفاقية بعد نشرها بالوقائع المصرية وذلك بناء على اتفاق بين الطرفين الراغبين فى الانضمام ودون حاجة إلى موافقة طرفى الاتفاقية الأصليين . ويكون الانضمام بطلب موقع من الطرفين يقدم إلى الجهة الإدارية المختصة ."}, {"number": "161", "chapter": "الباب الثالث", "text": "على الجهة الإدارية المختصة التأشير على هامش السجل بما يطرأ على الاتفاقية الجماعية من تجديد أو انضمام أو تعديل ونشر ملخص لتأشير فى الوقائع المصرية خلال خمسة عشر يوماُ من تاريخ حصوله ."}, {"number": "162", "chapter": "الباب الثالث", "text": "يلتزم طرفا الاتفاقية الجماعية بتنفيذها بطريقة تتفق مع ما يقتضيه حسن النية وأن يمتنعا عن القيام بأي عمل أو إجراء من شأنه أن يعطل تنفيذ أحكامها ."}, {"number": "163", "chapter": "الباب الثالث", "text": "إذا طرأت ظروف استثنائية غير متوقعة وترتب على حدوثها أن تنفيذ أحد الطرفين للاتفاقية أو لحكم من أحكامها أصبح مرهقاً وجب على الطرفين سلوك طريق المفاوضة الجماعية لمناقشة هذه الظروف والوصول إلى اتفاق يحقق التوازن بين مصلحتيهما . فإذا لم يصل الطرفان إلى اتفاق كان لأي منهما عرض الأمر على الجهة الإدارية المختصة لاتخاذ ما يلزم نحو إتباع إجراءات الوساطة وفقاً لأحكام المادة (170) من هذا القانون ."}, {"number": "164", "chapter": "الباب الثالث", "text": "لكل من طرفي الاتفاقية الجماعية وكذلك لكل ذى مصلحة من العمال أو أصحاب الأعمال أن يطلب الحكم بتنفيذ أى من أحكامها أو بالتعويض عن عدم التنفيذ وذلك على الممتنع عن التنفيذ أو المخالف للالتزامات الواردة بالاتفاقية ، ولا يحكم بالتعويض على المنظمة النقابية أو منظمة أصحاب الأعمال إلا إذا كان التصرف الذي ترتب عليه الضرر الموجب للتعويض قد صدر عن مجلس إدارة المنظمة أو الممثل القانوني لها ."}, {"number": "165", "chapter": "الباب الثالث", "text": "للمنظمة النقابية ولمنظمات أصحاب الأعمال التى تكون طرفاً فى الاتفاقية الجماعية أن ترفع لمصلحة أى عضو من أعضائها جميع الدعاوى الناشئة عن الإخلال بأحكام الاتفاقية وذلك دون حاجة إلى توكيل منه بذلك . وللعضو الذى رفعت الدعوى من المنظمة لمصلحته أن يتدخل فيها كما يجوز له رفع هذه الدعوى ابتداء مستقلا عنها ."}, {"number": "166", "chapter": "الباب الثالث", "text": "تخضع المنازعات الخاصة بأي حكم من أحكام الاتفاقية الجماعية للإجراءات التى يتفق عليها الطرفان فى الاتفاقية . فإذا لم ترد هذه الإجراءات فى الاتفاقية خضعت تلك المنازعات للأحكام الخاصة بتسوية منازعات العمل الجماعية الواردة فى الباب الرابع من الكتاب الرابع من هذا القانون ."}, {"number": "167", "chapter": "الباب الثالث", "text": "تقوم الوزارة المختصة بإنشاء وحدة إدارية تختص بشئون المفاوضات والاتفاقيات الجماعية ومراقبة تطبيقها . ويصدر الوزير المختص بالاتفاق مع منظمات العمال ومنظمات أصحاب الأعمال قراراً يحدد فيه مستويات التفاوض الجماعى وموضوعاته والإجراءات التي تتبع فى شأنه على المستويين القومى والإقليمي والمستويات الأدنى . ويصدر الوزير المختص قراراً يتضمن عقد عمل جماعى نموذجى يسترشد به أطراف المفاوضة ."}, {"number": "168", "chapter": "الباب الرابع", "text": "مع عدم الإخلال بحق التقاضى تسرى أحكام هذا الباب على كل نزاع يتعلق بشروط العمل أو ظروفه أو أحكام الاستخدام ينشأ بين صاحب عمل أو مجموعة من أصحاب الأعمال وبين جميع العمال أو فريق منهم ."}, {"number": "169", "chapter": "الباب الرابع", "text": "إذا ثار نزاع مما نص عليه فى المادة السابقة وجب على طرفيه الدخول فى مفاوضة جماعية لتسويته ودياً ."}, {"number": "170", "chapter": "الباب الرابع", "text": "إذا لم تتم تسوية النزاع كلياً خلال ثلاثين يوماً من تاريخ بدء المفاوضات جاز للطرفين أو لأحدهما أو لمن يمثلهما التقدم بطلب إلى الجهة الإدارية المختصة لاتخاذ إجراءات الوساطة ."}, {"number": "171", "chapter": "الباب الرابع", "text": "تعد فى الوزارة المختصة قائمة بالوسطاء يصدر بها قرار من الوزير المختص بالتشاور مع الاتحاد العام لنقابات عمال مصر ومنظمات أصحاب الأعمال . ويصدر بتحديد شروط القيد في قائمة الوسطاء قرار من الوزير المختص ."}, {"number": "172", "chapter": "الباب الرابع", "text": "يجب أن تتوافر فى وسيط النزاع الذى يتم اختياره من قائمة الوسطاء: أ - أن يكون ذا خبرة فى موضوع النزاع . ب - ألا يكون له مصلحة فى النزاع . ج - ألا يكون قد سبق اشتراكه بآية صورة فى بحث النزاع أو محاولة تسويته . وتحدد الجهة الإدارية المختصة بمناسبة كل نزاع الجهة أو الجهات التي تتحمل نفقات الوساطة ، والمدة التى يتعين خلالها على الوسيط إنهاء مهمته بحد أقصى خمسة وأربعون يوماً ."}, {"number": "173", "chapter": "الباب الرابع", "text": "يقوم الطرفان باختيار الوسيط من بين المقيدين فى قائمة الوسطاء المنصوص عليها فى المادة (171) من هذا القانون ، وإبلاغ الجهة الإدارية المختصة به ، وذلك خلال ثمانية أيام من تاريخ تقديم الطلب ، وتتولى هذه الجهة إخطار الوسيط الذى وقع عليه الاختيار . فإذا تبين لهذه الجهة فقدان الوسيط المختار لأي من الشروط المنصوص عليها فى المادة (172) من هذا القانون أو انقضت المدة المشار إليها فى الفقرة السابقة دون قيام الطرفين باختيار الوسيط تولت الجهة الإدارية المختصة تعيينه من بين المقيدين فى القائمة المشار إليها وذلك خلال العشر أيام التالية ."}, {"number": "174", "chapter": "الباب الرابع", "text": "تبدأ مهمة الوسيطً من تاريخ إخطار الجهة الإدارية المختصة له باختياره أو تعيينه ويرفق بالإخطار الأوراق الخاصة بالنزاع . وعلى الوسيط إنجاز مهمته خلال المدة المحددة له تطبيقاً لحكم المادة (172) من هذا القانون وله أن يستعين فى أداء مهمته بمن يلزم من ذوى الخبرة ."}, {"number": "175", "chapter": "الباب الرابع", "text": "للوسيط كافة الصلاحيات فى سبيل فحص النزاع والإلمام بعناصره ، وله على وجه الخصوص سماع طرفي النزاع والإطلاع على ما يلزم من مستندات ، وعلى الطرفين تقديم ما يطلبه الوسيط من البيانات والمعلومات التي تعينه على أداء مهمته ."}, {"number": "176", "chapter": "الباب الرابع", "text": "على الوسيط أن يبذل مساعيه للتقريب بين وجهات نظر طرفى النزاع ، فإذا لم يتمكن من تحقيق ذلك كان عليه أن يقدم للطرفين كتابة ما يقترحه من توصيات لحل النزاع ."}, {"number": "177", "chapter": "الباب الرابع", "text": "إذا قبل الطرفان التوصيات التى قدمها الوسيط أو بعضها وجب إثبات ذلك فى اتفاقية يوقعها الطرفان والوسيط . ويجب أن يكون رفض الطرفين أو أحدهما للتوصيات المشار إليها كلها أو بعضها مسبباً ، ويجوز للوسيط فى هذه الحالة إعطاء مهلة أقصاها ثلاثة أيام لمن رفض التوصيات للعدول عن الرفض ، وذلك قبل أن يقدم الوسيط تقريره إلى الجهة الإدارية المختصة ."}, {"number": "178", "chapter": "الباب الرابع", "text": "على الوسيط أن يقدم خلال أسبوع من تاريخ انتهاء المهلة المشار إليها فى المادة السابقة تقريراً للجهة الإدارية المختصة يتضمن ملخصاً للنزاع وبيانا مسبباُ بالتوصيات التى انتهى إليها وما تم من قبول أو رفض لها من الطرفين أو من أحدهما وأسباب الرفض ."}, {"number": "179", "chapter": "الباب الرابع", "text": "إذا لم يقبل الطرفان أو أحدهما التوصيات التي قدمها الوسيط ، كان لأي منهما أن يتقدم للجهة الإدارية المختصة بطلب اتخاذ إجراءات التحكيم ."}, {"number": "180", "chapter": "الباب الرابع", "text": "يجب أن يكون طلب التحكيم المقدم من صاحب العمل موقعاً منه أو من وكيله المفوض . فإذا كان الطلب من العمال وجب تقديمه من رئيس اللجنة النقابية إن وجدت أو من النقابة العامة المختصة ، وذلك كله بعد موافقة مجلس إدارة النقابة العامة . وتتولى الجهة الإدارية المختصة إحالة ملف النزاع إلى هيئة التحكيم، وذلك خلال يومين من تاريخ تقديم الطلب ."}, {"number": "181", "chapter": "الباب الرابع", "text": "لأي من طرفي النزاع فى المنشآت الاستراتيجية والحيوية المشار إليها فى المادة (194) من هذا القانون عند عدم تسوية النزاع ودياً من خلال المفاوضة أن يطلب من الجهة الإدارية المختصة إحالته مباشرة إلى هيئة التحكيم وذلك دون سلوك سبيل الوساطة ، ويجب أن يرفق بالطلب مذكرة شارحة لموضوع النزاع . وعلي الجهة الإدارية المختصة إحالة النزاع إلى هيئة التحكيم خلال أسبوع على الأكثر من تاريخ تقديم طلب التحكيم ."}, {"number": "182", "chapter": "الباب الرابع", "text": "تشكل هيئة التحكيم من: 1 - إحدى دوائر محاكم الاستئناف التي تحددها الجمعية العمومية لكل محكمة فى بداية كل سنة قضائية ، والتي يقع فى دائرة اختصاصها المركز الرئيسي للمنشأة وتكون لرئيس هذه الدائرة رئاسة الهيئة . 2 - محكم عن صاحب العمل . 3 - محكم عن التنظيم النقابى تختاره النقابة العامة المعنية . 4- محكم عن الوزارة المختصة يختاره الوزير المختص . وعلى كل من صاحب العمل والتنظيم النقابى والوزارة المختصة أن يختار محكماً احتياطيا يحل محل المحكم الأصلى عند غيابه ."}, {"number": "183", "chapter": "الباب الرابع", "text": "تتولى نظر النزاع هيئة التحكيم التى يقع فى دائرة اختصاصها المركز الرئيسي للمنشأة وتطبق فيما لم يرد بشأنه نص خاص فى هذا الباب أحكام قانون التحكيم فى المواد المدنية والتجارية، وقانون المرافعات المدنية والتجارية ."}, {"number": "184", "chapter": "الباب الرابع", "text": "يحدد رئيس هيئة التحكيم جلسة لنظر النزاع لا يجاوز ميعادها خمسة عشر يوماً من تاريخ ورود ملف النزاع إلى الهيئة ، ويخطر أعضاء الهيئة وممثل الوزارة المختصة وطرفا النزاع للجلسة المحددة قبل ثلاثة أيام على الأقل من تاريخها بكتاب موصى عليه بعلم الوصول ."}, {"number": "185", "chapter": "الباب الرابع", "text": "يحلف المحكم قبل مباشرة عمله اليمين أمام رئيس هيئة التحكيم بأن يؤدي مهمته بالذمة والصدق ."}, {"number": "186", "chapter": "الباب الرابع", "text": "تفصل هيئة التحكيم فى النزاع المعروض عليها فى مدة لا تجاوز شهرا من بدء نظره ، وللهيئة أن تقرر سماع الشهود وندب أهل الخبرة ومعاينة محال العمل والإطلاع على جميع المستندات الخاصة بالنزاع واتخاذ الإجراءات التى تمكنها من الفصل فيه ."}, {"number": "187", "chapter": "الباب الرابع", "text": "تطبق هيئة التحكيم القوانين المعمول بها ، فإذا لم يوجد نص تشريعي يمكن تطبيقه حكم القاضى بمقتضى العرف ، فإذا لم يوجد فبمقتضى مبادئ الشريعة الإسلامية فإذا لم توجد فبمقتضى مبادئ القانون الطبيعى وقواعد العدالة وفقاً للحالة الاقتصادية والاجتماعية السائدة فى منطقة المنشأة . ويصدر الحكم بأغلبية الآراء ، فإذا تساوت يرجح الجانب الذى منه الرئيس ويكون مسبباً ويعتبر بمثابة حكم صادر عن محكمة الاستئناف بعد تذييله بالصيغة التنفيذية ."}, {"number": "188", "chapter": "الباب الرابع", "text": "على هيئة التحكيم إعلان كل من طرفى النزاع بصورة من الحكم بكتاب مسجل موصى عليه مصحوباً بعلم الوصول ، وذلك خلال ثلاثة أيام من تاريخ صدوره . وترسل الهيئة ملف النزاع بعد إخطار طرفيه إلى الجهة الإدارية المختصة لقيد منطوق الحكم فى سجل خاص ، ويكون لكل ذى شأن حق الحصول على صورة من هذا الحكم . ولكل من طرفى النزاع أن يطعن فى الحكم أمام محكمة النقض . وتتبع فى الإعلان والطعن الشروط والأوضاع والإجراءات المقررة فى قانون التحكيم فى المواد المدنية والتجارية ."}, {"number": "189", "chapter": "الباب الرابع", "text": "تطبق على الأحكام الصادرة عن هيئة التحكيم القواعد الخاصة بتصحيح الأحكام وتفسيرها المنصوص عليها فى قانون التحكيم فى المواد المدنية والتجارية ."}, {"number": "190", "chapter": "الباب الرابع", "text": "تختص هيئة التحكيم بنظر الإشكالات فى تنفيذ الأحكام الصادرة عنها ، وذلك وفقاً للقواعد المقررة فى قانون التحكيم فى المواد المدنية والتجارية . ويحدد وزير العدل بقرار يصدره بالاتفاق مع الوزير المختص عدد هيئات التحكيم فى نطاق كل محكمة من محاكم الاستئناف ، وتتولى الجمعيات العمومية لهذه المحاكم فى بداية كل سنة قضائية تحديد الدوائر التي تدخل فى تشكيل هذه الهيئات . ويتضمن القرار المشار إليه تحديد بدل حضور الجلسات للمحكمين عن أصحاب الأعمال والتنظيم النقابي والوزارة المختصة ."}, {"number": "191", "chapter": "الباب الرابع", "text": "عدا المنشآت الاستراتيجية والحيوية المشار إليها في المادة (194) من هذا القانون ، يجوز لصاحب العمل أو التنظيم النقابى فى حالة عدم قبول أي منهما للتوصيات التى ينتهى إليها الوسيط فى النزاع الذي ينشأ بينهما الاتفاق على اللجوء للتحكيم الخاص بدلا من هيئة التحكيم المنصوص عليها فى هذا الباب . ويحدد الطرفان فى وثيقة التحكيم الموقعة منهما موضوع النزاع والشروط والإجراءات التي تتبع فى التحكيم الخاص وعدد المحكمين وبشرط أن يكون عددهم وتراً . ويكون حكم التحكيم ملزماً للطرفين بعد إيداع المحكم أو المحكمين أصل الحكم وأصل وثيقة التحكيم قلم كتاب المحكمة التي يقع فى دائرة اختصاصها المركز الرئيسي للمنشأة ويكون هذا الحكم قابلا للتنفيذ بأمر يصدره قاضى التنفيذ بالمحكمة التي أودع أصل الحكم قلم كتابها بناء على طلب أى من ذوى الشأن . ويختص قاضى التنفيذ بكل ما يتعلق بتنفيذ حكم التحكيم . ويتبع فيما لم تتضمنه أحكام هذه المادة ووثيقة التحكيم الأحكام المقررة فى قانون التحكيم فى المواد المدنية والتجارية ."}, {"number": "192", "chapter": "الباب الرابع", "text": "للعمال حق الإضراب السلمي ويكون إعلانه وتنظيمه من خلال منظماتهم النقابية دفاعا عن مصالحهم المهنية والاقتصادية والاجتماعية ، وذلك فى الحدود وطبقاً للضوابط والإجراءات المقررة فى هذا القانون . وفى حالة اعتزام عمال المنشأة ذات اللجنة النقابية الإضراب فى الأحوال التي يجيزها هذا القانون ، يجب على اللجنة النقابية بعد موافقة مجلس إدارة النقابة العامة المعنية بأغلبية ثلثى عدد أعضائه إخطار كل من صاحب العمل والجهة الإدارية المختصة قبل التاريخ المحدد للإضراب بعشرة أيام على الأقل وذلك بكتاب مسجل بعلم الوصول . فإذا لم يكن بالمنشأة لجنة نقابية يكون الإخطار باعتزام العمال الإضراب للنقابة العامة المعنية ، وعلى الأخيرة بعد موافقة مجلس إدارتها بالأغلبية المنصوص عليها فى الفقرة السابقة القيام بالإخطار المشار إليه . وفى جميع الأحوال يتعين أن يتضمن الإخطار الأسباب الدافعة للإضراب والمدة الزمنية المحددة له ."}, {"number": "193", "chapter": "الباب الرابع", "text": "يحظر على العمال الإضراب أو إعلانه بواسطة منظماتهم النقابية بقصد تعديل اتفاقية العمل الجماعية أثناء مدة سريانه ، وكذلك خلال جميع مراحل وإجراءات الوساطة والتحكيم ."}, {"number": "194", "chapter": "الباب الرابع", "text": "يحظر الإضراب أو الدعوة إليه فى المنشآت الاستراتيجية أو الحيوية التي يترتب على توقف العمل فيها الإخلال بالأمن القومى أو بالخدمات الأساسية التي تقدمها للمواطنين . ويصدر قرار من رئيس مجلس الوزراء بتحديد هذه المنشآت ."}, {"number": "195", "chapter": "الباب الرابع", "text": "يترتب على الإضراب المشار إليه فى المادة (192) من هذا القانون احتساب مدته إجازة للعمل بدون أجر ."}, {"number": "196", "chapter": "الباب الرابع", "text": "يكون لصاحب العمل ، لضرورات اقتصادية ، حق الإغلاق الكلى أو الجزئى للمنشأة أو تقليص حجمها أو نشاطها بما قد يمس حجم العمالة بها وذلك فى الأوضاع وبالشروط والإجراءات المنصوص عليها فى هذا القانون ."}, {"number": "197", "chapter": "الباب الرابع", "text": "فى تطبيق أحكام المادة السابقة على صاحب العمل أن يتقدم بطلب إغلاق المنشأة أو تقليص حجمها أو نشاطها إلى لجنة تشكل لهذا الغرض . ويتضمن الطلب الأسباب التي يستند إليها فى ذلك وأعداد وفئات العمال الذين سيتم الاستغناء عنهم . وعلى اللجنة أن تصدر قرارها مسبباً خلال ثلاثين يوما على الأكثر من تاريخ تقديم الطلب إليها فإذا كان القرار صادراً بقبول الطلب وجب أن يشتمل على بيان تاريخ تنفيذه . ولصاحب الشأن أن يتظلم من هذا القرار أمام لجنة أخرى تشكل لهذا الغرض ويترتب على التظلم من القرار الصادر بقبول الطلب وقف تنفيذه . ويصدر قرار من رئيس مجلس الوزراء بتشكيل كل من اللجنتين المشار إليهما وتحديد اختصاصاتهما والجهات التي تمثل فيهما والإجراءات التي تتبع أمامهما ومواعيد وإجراءات التظلم . ويراعى أن يتضمن تشكيل كل من اللجنتين ممثلا عن المنظمة النقابية العمالية المعنية يرشحه الاتحاد العام لنقابات عمال مصر ، وممثلا عن منظمات أصحاب الأعمال ترشحه المنظمة المعنية بنشاط المنشأة ."}, {"number": "198", "chapter": "الباب الرابع", "text": "يخطر صاحب العمل العمال والمنظمة النقابية المعنية بالطلب المقدم منه وبالقرار الصادر بالإغلاق الكلى أو الجزئى للمنشأة أو بتقليص حجمها أو نشاطها . ويكون تنفيذ ذلك القرار اعتباراً من التاريخ الذى تحدده اللجنة التى نظرت الطلب أو التظلم على حسب الأحوال ."}, {"number": "199", "chapter": "الباب الرابع", "text": "فى حالة الإغلاق الجزئي أو تقليص حجم المنشاة أو نشاطها ، إذا لم تتضمن الاتفاقية الجماعية السارية فى المنشأة المعايير الموضوعية لاختيار من سيتم الاستغناء عنهم من العمال ، فإنه يتعين على صاحب العمل أن يتشاور فى هذا الشأن مع المنظمة النقابية وذلك بعد صدور القرار وقبل التنفيذ وتعتبر الأقدمية والأعباء العائلية والسن والقدرات والمهارات المهنية للعمال من المعايير التي يمكن الاستئناس بها من هذا الشأن . وفى جميع الأحوال يتعين أن تراعى تلك المعايير الموازنة بين مصالح المنشأة ومصالح العمال ."}, {"number": "200", "chapter": "الباب الرابع", "text": "يحظر على صاحب العمل التقدم بطلب الإغلاق الكلى أو الجزئي للمنشأة أو تقليص حجمها أو نشاطها أثناء مراحل الوساطة والتحكيم ."}, {"number": "201", "chapter": "الباب الرابع", "text": "مع عدم الإخلال بحكم المادة (198) من هذا القانون وفى الحالات التي يحق فيه لصاحب العمل إنهاء عقد العمل لأسباب اقتصادية يجوز له بدلاً من استخدام هذا الحق أن يعدل من شروط العقد بصفة مؤقتة وله على الأخص أن يكلف العامل بعمل غير متفق عليه ولو كان يختلف عن عمله الأصلى كما أن له أن ينقص أجر العامل بما لا يقل عن الحد الأدنى للأجور . فإذا قام صاحب العمل بتعديل فى شروط العقد وفقاً للفقرة السابقة كان للعامل أن ينهى عقد العمل دون أن يلتزم بالإخطار ويعتبر الإنهاء فى هذه الحالة إنهاء مبرراً من جانب صاحب العمل ويستحق العامل المكافأة المنصوص عليها بالفقرة التالية ويلتزم صاحب العمل عند إنهاء العقد لأسباب اقتصادية وفقاً للإجراءات المبين بالمواد من (196 إلى 200) من هذا القانون بأن يؤدي للعامل الذي أنهى عقده مكافأة تعادل الأجر الشامل لشهر عن كل سنة من الخمس سنوات الأولى من سنوات الخدمة وشهر ونصف عن كل سنة تجاوز ذلك ."}, {"number": "202", "chapter": "الباب الأول", "text": "يقصد فى تطبيق أحكام هذا الكتاب بالمصطلحات الآتية المعاني المبينة قرين كل منها: 1- إصابة العمل ، والأمراض المهنية ، والأمراض المزمنة التعاريف الواردة لها فى قانون التأمين الاجتماعى وقراراته التنفيذية . 2- المنشأة: كل مشروع أو مرفق يملكه أو يديره شخص من أشخاص القانون العام أو الخاص . 3- المنشأة في تطبيق أحكام الباب الرابع من هذا الكتاب: كل مشروع أو مرفق يملكه أو يديره شخص من أشخاص القانون الخاص ."}, {"number": "203", "chapter": "الباب الأول", "text": "تسرى أحكام هذا الكتاب على جميع مواقع العمل ، والمنشآت وفروعها أياً كان نوعها أو تبعيتها سواء كانت برية أو بحرية . كما تسرى أيضاً على المسطحات المائية بجميع أنواعها ووسائل النقل المختلفة ."}, {"number": "204", "chapter": "الباب الثانى", "text": "الباب الثاني مواقع العمل والإنشاءات والتراخيص يراعى عند اختيار مواقع العمل والمنشآت وفروعها ومنح التراخيص الخاصة بها مقتضيات حماية البيئة طبقاً لأحكام التشريعات الصادرة في هذا الشأن ."}, {"number": "205", "chapter": "الباب الثانى", "text": "تشكل في وزارة الصناعة لجنة مركزية برئاسة رئيس الإدارة المركزية المختصة في هذه الوزارة وعضوية كل من رؤساء الإدارات المركزية المختصين بوزارات القوى العاملة والهجرة والإسكان والصحة والموارد المائية والرى والكهرباء الداخلية وشئون البيئة . ويصدر بتشكيل هذه اللجنة قرار من الوزير المختص بالاتفاق مع الوزراء المعنيين ، وتختص هذه اللجنة بما يلى: 1- وضع معايير واشتراطات منح تراخيص المحال والمنشآت الصناعية التي تنشئها أو تديرها الوزارات أو الهيئات العامة والوحدات الاقتصادية التابعة لها أو شركات قطاع الأعمال العام أو شركات القطاع العام . 2- الموافقة على اتخاذ إجراءات منح التراخيص للمحال والمنشآت المشار إليها على أن يكون إصدار التراخيص من وحدات الإدارة المحلية المختصة ، مع عدم الإخلال بأحكام القوانين الصادرة فى هذا الشأن ."}, {"number": "206", "chapter": "الباب الثانى", "text": "تشكل لجنة بكل محافظة برئاسة سكرتير عام المحافظة وعضوية ممثلي الوزارات بالمحافظات المختلفة المشار إليها فى المادة السابقة . ويصدر بتشكيل هذه اللجنة قرار من المحافظ المختص وتختص بما يلي: (أ) متابعة اتخاذ إجراءات منح التراخيص للمحال والمنشآت المشار إليها في المادة المذكورة ومتابعة تنفيذ الاشتراطات التي وضعتها اللجنة المركزية في هذا الخصوص . (ب) منح الموافقات وإصدار التراخيص بالنسبة لمحال ومنشآت القطاع الاستثماري بنفس المعايير والاشتراطات التي تضعها اللجنة المركزية ."}, {"number": "207", "chapter": "الباب الثانى", "text": "تشكل لجنة محلية على مستوى كل من : المركز والمدينة والحى ، وذلك من ممثلى الأجهزة القائمة على شئون الإسكان والقوى العاملة والهجرة والصحة والكهرباء والبيئة بالوحدات المحلية . ويصدر بتشكيل هذه اللجنة قرار من رئيس الوحدة المحلية المختص وتختص هذه اللجنة دون غيرها بما يلي : (أ) منح الموافقات وإصدار التراخيص للمحال والمنشآت التابعة للقطاع الخاص ، وذلك فيما عدا المحال والمنشآت الصغيرة التى يحددها ويبين اشتراطات إنشائها قرار من وزير الإسكان . (ب) تحديد الاشتراطات الخاصة الواجب توافرها فى المحال أو المنشأة موضوع طلب الترخيص والتأكد من استيفاء هذه الاشتراطات قبل إصدارها . ويتعين موافقة أجهزة السلامة والصحة المهنية التابعة لوزارة القوى العاملة والهجرة على منح التراخيص للمحال والمنشآت التى يكون إصدار التراخيص لها من جهات أخرى ، وذلك قبل إصدار هذه التراخيص وعند إجراء أي تعديل بها ."}, {"number": "208", "chapter": "الباب الثالث", "text": "تلتزم المنشأة وفروعها بتوفير وسائل السلامة والصحة المهنية وتأمين بيئة العمل في أماكن العمل بما يكفل الوقاية من المخاطر الفيزيائية الناجمة عما يلى بوجه خاص: (أ) الوطأة الحرارية والبرودة . (ب) الضوضاء والاهتزازات . (ج) الإضاءة . (د) الإشعاعات الضارة والخطرة . (هـ) تغيرات الضغط الجوي . (و) الكهرباء الاستاتيكية والديناميكية . (ز) مخاطر الانفجار ."}, {"number": "209", "chapter": "الباب الثالث", "text": "تلتزم المنشأة وفروعها باتخاذ جميع الاحتياطات والتدابير اللازمة لتوفير وسائل السلامة والصحة المهنية وتأمين بيئة العمل للوقاية من المخاطر الميكانيكية والتي تنشأ من الاصطدام بين جسم العامل وبين جسم صلب وعلى الأخص: (أ) كل خطر ينشأ عن آلات وأدوات العمل من أجهزة وآلات وأدوات رفع وجر ووسائل الانتقال والتداول ونقل الحركة . (ب) كل خطر ينشأ عن أعمال التشييد والبناء والحفر ومخاطر الانهيار والسقوط ."}, {"number": "210", "chapter": "الباب الثالث", "text": "تلتزم المنشأة وفروعها باتخاذ وسائل وقاية العمال من خطر الإصابة بالبكتريا والفيروسات والفطريات والطفيليات وسائر المخاطر البيولوجية متى كانت طبيعة العمل تعرض العمال لظروف الإصابة بها وعلى الأخص: (أ) التعامل مع الحيوانات المصابة ومنتجاتها ومخلفاتها . (ب) مخالطة الآدميين المرضى والقيام بخدماتهم من رعاية وتحاليل وفحوص طبية ."}, {"number": "211", "chapter": "الباب الثالث", "text": "تلتزم المنشأة وفروعها بتوفير وسائل الوقاية من المخاطر الكيميائية الناتجة عن التعامل مع المواد الكيميائية الصلبة والسائلة والغازية مع مراعاة ما يلي: (أ) عدم تجاوز أقصي تركيز مسموح به للمواد الكيماوية والمواد المسببة للسرطان التى يتعرض لها العمال . (ب) عدم تجاوز مخزون المواد الكيميائية الخطرة كميات العتبة لكل منها . (ج) توفير الاحتياطات اللازمة لوقاية المنشأة والعمال عند نقل وتخزين وتداول وإستخدام المواد الكيميائية الخطرة والتخلص من نفاياتها . (د) الاحتفاظ بسجل لحصر المواد الكيميائية الخطرة المتداولة متضمنا جميع البيانات الخاصة بكل مادة وبسجل لرصد بيئة العمل وتعرض العمال لخطر الكيماويات . (هـ) وضع بطاقات تعريف لجميع المواد الكيميائية المتداولة في العمل موضحا بها الاسم العلمى والتجارى والتركيب الكيميائي لها ودرجة خطورتها واحتياطات السلامة وإجراءات الطوارئ المتعلقة بها ، وعلي المنشأة أن تحصل على البيانات المذكورة في هذه المواد من موردها عند التوريد . (و) تدريب العمال علي طرق التعامل مع المواد الكيميائية الخطرة والمواد المسببة للسرطان وتعريفهم وتبصيرهم بمخاطرها وبطرق الأمان والوقاية من هذه المخاطر ."}, {"number": "212", "chapter": "الباب الثالث", "text": "تلتزم المنشأة وفروعها بتوفير وسائل الوقاية من المخاطر السلبية والتي تنشأ أو يتفاقم الضرر أو الخطر من عدم توافرها ، كوسائل الإنقاذ والإسعاف والنظافة والترتيب والتنظيم بأماكن العمل ، والتأكد من حصول العاملين بأماكن طهو وتناول الأطعمة والمشروبات علي الشهادات الصحية الدالة علي خلوهم من الأمراض الوبائية والمعدية ."}, {"number": "213", "chapter": "الباب الثالث", "text": "يصدر الوزير المختص قراراً ببيان حدود الأمان والاشتراطات والاحتياطات اللازمة لدرء المخاطر المبينة بالمواد ( 208 ، 209 ، 210، 211، 212) من هذا القانون وذلك بعد أخذ رأي الجهات المعنية ."}, {"number": "214", "chapter": "الباب الثالث", "text": "تلتزم المنشأة وفروعها باتخاذ الاحتياطات والاشتراطات اللازمة للوقاية من مخاطر الحريق طبقاً لما تحدده الجهة المختصة بوزارة الداخلية وحسب طبيعة النشاط الذى تزاوله المنشأة والخواص الفيزيائية والكيميائية للمواد المستخدمة والمنتجة مع مراعاة ما يأتي: (أ) أن تكون كافة أجهزة وأدوات الإطفاء المستخدمة مطابقة للمواصفات القياسية المصرية . (ب) تطوير معدات الإطفاء والوقاية باستخدام أحدث الوسائل وتوفير أجهزة التنبيه والتحذير والإنذار المبكر والعزل الوقائى والإطفاء الآلي التلقائي كلما كان ذلك ضرورياً ، بحسب طبيعة المنشأة ونشاطها ."}, {"number": "215", "chapter": "الباب الثالث", "text": "تلتزم المنشأة وفروعها بإجراء تقييم وتحليل للمخاطر والكوارث الصناعية والطبيعية المتوقعة وإعداد خطة طوارئ لحماية المنشأة والعمال بها عند وقوع الكارثة ، على أن يتم اختبار فاعلية هذه الخطة وإجراء بيانات عملية عليها للتأكد من كفاءتها وتدريب العمال لمواجهة متطلباتها . وتلتزم المنشأة بإبلاغ الجهة الإدارية المختصة بخطة الطوارئ وبأية تعديلات تطرأ عليها ، وكذلك في حالة تخزين مواد خطرة أو استخدامها . وفي حالة امتناع المنشأة عن تنفيذ ما توجبه الأحكام السابقة والقرارات المنفذة لها في المواعيد التي تحددها الجهة الإدارية المختصة ، وكذلك في حالة وجود خطر داهم على صحة العاملين أو سلامتهم ، يجوز لهذه الجهة أن تأمر بإغلاق المنشأة كلياً أو جزئياً أو بإيقاف آلة أو أكثر حتى تزول أسباب الخطر . وينفذ القرار الصادر بالإغلاق أو بالإيقاف بالطرق الإدارية مع عدم الإخلال بحق العاملين في تقاضي أجورهم كاملة خلال فترة الإغلاق أو الإيقاف . وللجهة الإدارية المختصة أن تقوم بإزالة أسباب الخطر بطريق التنفيذ المباشر على نفقة المنشأة ."}, {"number": "216", "chapter": "الباب الرابع", "text": "مع عدم الإخلال بأحكام قانون التأمين الاجتماعي تلتزم المنشأة وفروعها بإجراء ما يلي: (أ) الكشف الطبي على العامل قبل التحاقه بالعمل للتأكد من سلامته ولياقته الصحية طبقا لنوع العمل الذي يسند إليه . (ب) كشف القدرات للتأكد من لياقة العامل من ناحية قدراته الجسمانية والعقلية والنفسية بما يناسب احتياجات العمل . وتجري هذه الفحوص طبقا للأحكام المنظمة للتأمين الصحى ، ويصدر الوزير المختص بالاتفاق مع وزير الصحة قراراً بتحديد مستويات اللياقة والسلامة الصحية والقدرات العقلية والنفسية التي تتم على أساسها هذه الفحوص ."}, {"number": "217", "chapter": "الباب الرابع", "text": "تلتزم المنشأة وفروعها بما يأتي: (أ) تدريب العامل على الأسس السليمة لأداء مهنته . (ب) إحاطة العامل قبل مزاولة العمل بمخاطر مهنته وإلزامه باستخدام وسائل الوقاية المقررة لها مع توفير أدوات الوقاية الشخصية المناسبة وتدريبه على استخدامها . ولا يجوز للمنشأة أن تحمل العامل أية نفقات أو تقتطع من أجره أية مبالغ لقاء توفير وسائل الحماية اللازمة له ."}, {"number": "218", "chapter": "الباب الرابع", "text": "يلتزم العامل بأن يستعمل وسائل الوقاية ويتعهد بالعناية بما في حوزته منها وبتنفيذ التعليمات الصادرة للمحافظة علي صحته ووقايته من حوادث العمل ، وعليه ألا يرتكب أى فعل يقصد به منع تنفيذ التعليمات أو إساءة استعمال الوسائل الموضوعة لحماية وسلامة العمال المشتغلين معه أو تغييرها أو إلحاق ضرر أو تلف بها ، وذلك دون الإخلال بما يفرضه أى قانون أخر في هذا الشأن ."}, {"number": "219", "chapter": "الباب الرابع", "text": "تلتزم المنشأة وفروعها بإجراء ما يأتي: (أ) التفتيش الدوري اليومي في كل وردية عمل علي أماكن العمل الخاصة الخطرة منها لاكتشاف المخاطر المهنية والعمل على الوقاية منها . (ب) قيام طبيب المنشأة إن وجد بفحص شكوى العامل المرضية ومعرفة علاقاتها بنوع العمل . (ج) التنسيق مع الهيئة العامة للتأمين الصحى لإجراء الفحص الطبى الدورى لجميع عمال المنشأة للمحافظة على لياقتهم الصحية وسلامتهم بصفة مستمرة ولاكتشاف ما يظهر من أمراض مهنية في مراحلها الأولي ، ولإجراء الفحص عند انتهاء الخدمة ، وذلك كله طبقا لأنظمة التأمين الصحي المقررة في هذا الشأن ."}, {"number": "220", "chapter": "الباب الرابع", "text": "تلتزم المنشأة بأن توفر لعمالها وسائل الإسعافات الطبية . وإذا زاد عدد عمال المنشأة في مكان واحد أو بلد واحد أو في دائرة نصف قطرها خمسة عشر كيلو متر على خمسين عاملاً تلتزم المنشأة بأن تستخدم ممرضاً مؤهلاً أو أكثر لأعمال التمريض أو الإسعاف بكل وردية عمل بها ، وأن تعهد إلي طبيب بعيادتهم فى المكان الذى تعده لهذا الغرض ، وأن تقدم لهم الأدوية اللازمة للعلاج وذلك كله بالمجان . وإذا عولج العامل في الحالتين المنصوص عليهما في الفقرتين السابقتين في مستشفى حكومى أو خيرى وجب علي المنشأة أن تؤدى إلي إدارة المستشفى نفقات العلاج والأدوية والإقامة . ويتبع في تحديد نفقات العلاج والأدوية والإقامة المنصوص عليها في الفقرات السابقة الطرق والأوضاع التي يصدر بها قرار من الوزير المختص بالاتفاق مع وزير الصحة ."}, {"number": "221", "chapter": "الباب الرابع", "text": "يلتزم من يستخدم عمالاً في أماكن لا تصل إليها وسائل المواصلات العادية أن يوفر لهم وسائل الانتقال المناسبة . وعلى من يستخدم عمالاً في المناطق البعيدة عن العمران أن يوفر لهم التغذية المناسبة والمساكن الملائمة مع مراعاة تخصيص بعضها للعمال المتزوجين . ويصدر الوزير المختص بالاتفاق مع الوزراء المعنيين ومع الاتحاد العام لنقابات عمال مصر ومنظمات أصحاب الأعمال القرارات اللازمة لتحديد المناطق البعيدة عن العمران واشتراطات ومواصفات المساكن ، وتعيين أصناف الطعام والكميات التي تقدم منها لكل عامل وما يؤديه صاحب العمل مقابلاً لها . ويجوز بالنسبة لنظام الوجبات الغذائية الواردة فى الفقرة السابقة الأخذ بنظام توافق عليه إدارة المنشأة والعمال بها أو ممثلوهم بشرط أن يعتمد من الجهة الإدارية المختصة ، وعلى ألا يتضمن هذا النظام الاستعاضة عن تقديم هذه الوجبات كلها أو بعضها مقابل أى بدل نقدى ."}, {"number": "222", "chapter": "الباب الرابع", "text": "تلتزم المنشأة التى يبلغ عدد عمالها خمسين عاملاً فأكثر بتقديم الخدمات الاجتماعية والثقافية اللازمة لعمالها ، وذلك بالاشتراك مع اللجنة النقابية - إن وجدت - أو مع ممثلين للعمال تختارهم النقابة العامة المختصة . ويصدر قرار من الوزير المختص بعد موافقة الاتحاد العام لنقابات عمال مصر بتحديد الحد الأدنى لهذه الخدمات ."}, {"number": "223", "chapter": "الباب الرابع", "text": "ينشأ بالوزارة المختصة صندوق للخدمات الاجتماعية والصحية والثقافية على المستوى القومى . وتلتزم كل منشأة يبلغ عدد عمالها عشرين عاملاً فأكثر بدفع مبلغ لا يقل عن خمسة جنيهات سنوياُ عن كل عامل لتمويل هذا الصندوق . ويصدر الوزير المختص قراراً بتحديد الخدمات المشار إليها والمبلغ الذي تلتزم كل منشأة بأدائه بما لا يقل عن الحد الأدنى المذكور ، وذلك كله بالاتفاق مع الاتحاد العام لنقابات عمال مصر ومنظمات أصحاب الأعمال . كما يصدر الوزير المختص قراراً بتشكيل مجلس إدارة الصندوق مراعياً في هذا التشكيل التمثيل الثلاثي وبناء على ترشيح كل جهة لمن يمثلها . كما يصدر الوزير المختص قراراً باللائحة المالية والإدارية للصندوق متضمنة على وجه الخصوص كيفية التصرف في حصيلة المبالغ المشار إليها والإجراءات الخاصة بذلك ."}, {"number": "224", "chapter": "الباب الخامس", "text": "مع مراعاة الأحكام الواردة بالكتاب السادس من هذا القانون ، تلتزم الجهة الإدارية المختصة بما يأتي: 1- إعداد جهاز متخصص للتفتيش على المنشآت يتشكل من أعضاء تتوافر فيهم المؤهلات العلمية والخبرة اللازمة في مجالات الطب والهندسية والعلوم وغيرها . ويتولى الجهاز المشار إليه مراقبة تنفيذ أحكام السلامة والصحة المهنية وبيئة العمل ويتم التفتيش على أماكن العمل في فترات دورية مناسبة . 2- تنظيم برامج تدريبية متخصصة ونوعية لرفع كفاءة ومستوى أداء أفراد جهاز التفتيش المشار إليه في الفقرة السابقة ، وتزويدهم بالخبرات الفنية المتطورة بما يضمن أفضل مستويات السلامة والصحة المهنية وبيئة العمل . 3- تزويد جهاز التفتيش المشار إليه بأجهزة ومعدات القياس وكافة الإمكانيات اللازمة لأداء مهمته . ويكون التفتيش على المنشآت المتعلق عملها بالأمن القومى والتى تحدد بقرار من رئيس مجلس الوزراء بمعرفة الجهة التى يحددها هذا القرار ."}, {"number": "225", "chapter": "الباب الخامس", "text": "يكون لأفراد جهاز تفتيش السلامة والصحة المهنية وبيئة العمل في سبيل أداء عملهم: (أ) إجراء بعض الفحوص الطبية والمعملية اللازمة على العمال بالمنشآت للتأكد من ملاءمة ظروف العمل . (ب) أخذ عينات من المواد المستعملة أو المتداولة في العمليات الصناعية والتى قد يكون لها تأثير ضار على سلامة وصحة العمال أو بيئة العمل ، وذلك بغرض تحليلها والتعرف على الآثار الناتجة عن استخدامها وتداولها ، وإخطار المنشأة بذلك لاتخاذ ما يلزم فى هذا الشأن . (ج) استخدام المعدات والأجهزة وآلات التصوير وغيرها لتحليل أسباب الحوادث . (د) الإطلاع على خطة الطوارئ وتحليل المخاطر الخاصة بالمنشأة . (هـ) الإطلاع على نتائج التقارير الفنية والإدارية التى ترد للمنشأة عن أنواع الحوادث الجسيمة وأسبابها . (و) الإطلاع على كميات المخزون من المواد الخطرة التي تهدد المنشأة . ويكون للجهة الإدارية المختصة بناء على تقرير جهاز تفتيش السلامة والصحة المهنية وبيئة العمل الأمر بإغلاق المنشأة كلياً أو جزئياً أو إيقاف آلة أو أكثر ، وذلك في حالة وجود خطر داهم يهدد سلامة المنشأة أو صحة العمال أو سلامة بيئة العمل حتى تزول أسباب الخطر . وينفذ القرار الصادر بالإغلاق أو الإيقاف بالطرق الإدارية . وتصدر الجهة المشار إليها الأمر بإلغاء الإغلاق أو الإيقاف عند زوال أسباب الخطر ."}, {"number": "226", "chapter": "الباب الخامس", "text": "يكون حق التفتيش بالنسبة لاشتراطات السلامة والصحة المهنية وبيئة العمل الواردة في التراخيص لمفتشي السلامة والصحة المهنية وبيئة العمل تطبيقاً لأحكام القوانين والقرارات المنظمة لها ."}, {"number": "227", "chapter": "الباب السادس", "text": "يصدر الوزير المختص القرارات اللازمة بتحديد المنشآت وفروعها التي تلتزم بإنشاء أجهزة وظيفية للسلامة والصحة المهنية وتأمين بيئة العمل ، واللجان المختصة بذلك والجهات التى تتولى التدريب في هذه المجالات وتحدد هذه القرارات القواعد التى تتبع في هذا الشأن . وتختص اللجان المشار إليها ببحث ظروف العمل وأسباب الحوادث والإصابات والأمراض المهنية وغيرها ووضع القواعد والاحتياطات الكفيلة بمنعها ، وتكون قرارات هذه اللجان ملزمة للمنشآت وفروعها . ويجب أن يشمل التدريب العاملين بالجهاز الوظيفى للسلامة والصحة المهنية وتأمين بيئة العمل وأعضاء اللجان المختصة بذلك والمسئولين عن الإدارة والإنتاج بكافة مستوياتهم بما يتفق ومسئولياتهم وطبيعة عملهم ."}, {"number": "228", "chapter": "الباب السادس", "text": "تلتزم كل منشأة صناعية يعمل بها خمسة عشر عاملاً فأكثر ، وكل منشأة غير صناعية يعمل بها خمسون عاملاً فأكثر بموافاة مديرية القوى العاملة المختصة بإحصائية نصف سنوية عن الأمراض والإصابات ، وذلك خلال النصف الأول من شهرى يوليو ويناير على الأكثر . كما تلتزم كل منشأة من المنشآت الخاضعة لأحكام هذا الباب بإخطار المديرية المشار إليها بكل حادث جسيم يقع بالمنشأة وذلك خلال أربع وعشرين ساعة من وقوعه . ويصدر الوزير المختص قراراً بالنماذج التي تستخدم لهذا الغرض ."}, {"number": "229", "chapter": "الباب السابع", "text": "يختص المركز القومى لدراسات الأمن الصناعى بوضع الخطط المركزية للبحوث والدراسات في مجالات السلامة والصحة المهنية وتأمين بيئة العمل ، ويتابع تنفيذها بالتنسيق مع الأجهزة المعنية في الوزارة المختصة ، وذلك وفقاً للقواعد والإجراءات التى يصدر بها قرار من الوزير المختص ."}, {"number": "230", "chapter": "الباب السابع", "text": "يصدر بتشكيل المجلس الاستشارى الأعلى للسلامة والصحة المهنية وتأمين بيئة العمل قرار من رئيس مجلس الوزراء ، ويختص هذا المجلس برسم السياسة العامة في هذه المجالات واقتراح ما يلزم في شأن تنفيذ هذه السياسة . ويراعى في تشكيل المجلس أن يكون برئاسة الوزير المختص ، وعضوية ممثلين من الوزارات ذات الصلة ، وعدد متساو من ممثلى كل من منظمات أصحاب الأعمال والاتحاد العام لنقابات عمال مصر ، وعدد من ذوى الخبرة في مجال السلامة والصحة المهنية وبيئة العمل . ويصدر بتنظيم عمل هذا المجلس قرار من الوزير المختص ."}, {"number": "231", "chapter": "الباب السابع", "text": "تشكل في كل محافظة بقرار من المحافظ المختص لجنة استشارية للسلامة والصحة المهنية وتأمين بيئة العمل برئاسة المحافظ . وتضم في عضويتها ممثلين للجهات المعنية فى المحافظة ، وعدداً متساوياً من ممثلى منظمات أصحاب الأعمال وممثلى العمال فى المحافظة ، وعدداً من ذوى الخبرة . ويصدر بتحديد اختصاصات هذه اللجان ونظام العمل فيها قرار من الوزير المختص ."}, {"number": "232", "chapter": "الباب الأول", "text": "يكون للعاملين القائمين على تنفيذ أحكام هذا القانون والقرارات الصادرة تنفيذاً له والذين يصدر بتحديدهم قرار من وزير العدل بالاتفاق مع الوزير المختص صفة مأمورى الضبط القضائى بالنسبة للجرائم التي تقع في دوائر اختصاصهم وتكون متعلقة بأعمال وظائفهم . ويحلف كل منهم قبل مباشرة عمله يميناً أمام الوزير المختص بأن يقوم بأداء عمله بالأمانة والإخلاص وألا يفشى سراً من أسرار العمل أو الاختراعات التي يطلع عليها بحكم وظيفته حتى بعد تركه العمل ."}, {"number": "233", "chapter": "الباب الأول", "text": "يحمل العامل الذي له صفة الضبطية القضائية بطاقة تثبت هذه الصفة ، وله حق دخول جميع أماكن العمل وتفتيشها للتحقق من تطبيق أحكام هذا القانون والقرارات المنفذة له ، وفحص الدفاتر والأوراق المتعلقة بذلك ، وطلب المستندات والبيانات اللازمة من أصحاب الأعمال أو من ينوب عنهم . ويحدد الوزير المختص بقرار منه قواعد التكليف بتفتيش أماكن العمل ليلاً وفى غير أوقات العمل الرسمية للقائمين به والمكافآت التى تستحق لهم ."}, {"number": "234", "chapter": "الباب الأول", "text": "على أصحاب الأعمال أو من ينوب عنهم أن يسهلوا مهمة المكلفين بمراقبة تنفيذ أحكام هذا القانون والقرارات المنفذة له وأن يقدموا لهم المستندات والبيانات اللازمة لأداء مهمتهم ."}, {"number": "235", "chapter": "الباب الأول", "text": "على أصحاب الأعمال أو من ينوب عنهم الاستجابة لطلبات الحضور التي توجه إليهم من العاملين المشار إليهم في المادة (232) من هذا القانون وذلك في المواعيد التي يحددونها ."}, {"number": "236", "chapter": "الباب الأول", "text": "على السلطات المختصة مساعدة العاملين المكلفين بمراقبة تنفيذ هذا القانون والقرارات المنفذة له عند قيامهم بوظائفهم متى طلب ذلك منها ."}, {"number": "237", "chapter": "الباب الثانى", "text": "مع عدم الإخلال بأية عقوبة أشد ينص عليها أي قانون آخر ، يعاقب بالعقوبات المنصوص عليها فى المواد التالية عن الجرائم المشار إليها فيها ."}, {"number": "238", "chapter": "الباب الثانى", "text": "يعاقب كل من يخالف حكم الفقرة الثانية من المادة (13) من هذا القانون بغرامة لا تقل عن خمسين جنيهاً ولا تجاوز مائة جنيه ، وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة وتضاعف الغرامة في حالة العود ."}, {"number": "239", "chapter": "الباب الثانى", "text": "يعاقب كل من يخالف أياً من أحكام الفقرتين الأولى والثانية من المادة ( 15 ) من هذا القانون بغرامة لا تقل عن مائتي جنيه ولا تجاوز خمسة آلاف جنيه . ويكون الحد الأدنى للغرامة ألف جنيه عند مخالفة أي من أحكام الفقرة الثالثة من المادة المشار إليها ."}, {"number": "240", "chapter": "الباب الثانى", "text": "يعاقب كل من يخالف حكم الفقرة الثانية من المادة (16) من هذا القانون بغرامة لا تقل عن ألف جنيه ولا تجاوز خمسة آلاف جنيه وتتعدد الغرامة بتعدد العمال الذين وقعت في شأنهم الجريمة . وتضاعف الغرامة في حالة العود ."}, {"number": "241", "chapter": "الباب الثانى", "text": "يعاقب كل من يخالف أياً من أحكام القرارات الوزارية المنفذة للمادة ( 26 ) من هذا القانون بغرامة لا تقل عن خمسين جنيهاً ولا تجاوز خمسمائة جنيه وتتعدد الغرامة بتعدد العمال الذين وقعت في شأنهم الجريمة وتضاعف الغرامة في حالة العود ."}, {"number": "242", "chapter": "الباب الثانى", "text": "يعاقب بالحبس مدة لا تقل عن شهر ولا تجاوز سنة وبغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز عشرين ألف جنيه أو بإحدى هاتين العقوبتين كل من ارتكب إحدى الجرائم الآتية: 1 - مزاولة عمليات إلحاق المصريين بالعمل داخل جمهورية مصر العربية أو خارجها من غير الجهات المحددة في المادة ( 17 ) من هذا القانون دون الحصول على الترخيص المنصوص عليه فيها أو بترخيص صادر بناء على بيانات غير صحيحة . 2 - تقاضي مبالغ من العامل نظير إلحاقه بالعمل داخل جمهورية مصر العربية أو خارجها بالمخالفة لأحكام المادة ( 21 ) من هذا القانون أو تقاضى مبالغ دون وجه حق من أجر العامل أو من مستحقاته عن عمله في الداخل أو الخارج . 3 - مخالفة الأحكام الواردة بالفقرة الأولى من المادة ( 20 ) من هذا القانون أو تقديم بيانات غير صحيحة عن اتفاقيات أو عقود إلحاق المصرين بالعمل خارج جمهورية مصر العربية ، أو أجورهم أو نوعية أو ظروف عملهم أو أية شروط أخرى تتعلق بهذا العمل إلى الوزارة المختصة أو غيرها من الجهات المختصة . وفي جميع الأحوال يحكم برد المبالغ التي تم تقاضيها أو الحصول عليها دون وجه حق وتقضي المحكمة - من تلقاء نفسها- بالتعويضات للمضرور من الجريمة عما أصابه من ضرر بسبب الجريمة المنصوص عليها في البند (3) من هذه المادة ."}, {"number": "243", "chapter": "الباب الثانى", "text": "يعاقب بغرامة لا تقل عن ألفي جنيه ولا تجاوز عشرة آلاف جنيه كل من يخالف أياً من أحكام المادة ( 24 ) من هذا القانون أو القرارات الوزارية الصادرة تنفيذا لها ."}, {"number": "244", "chapter": "الباب الثانى", "text": "يقضي في الحكم الصادر بالإدانة في أي من الجرائم المنصوص عليها في المادتين السابقتين بغلق مقر المنشأة الذي وقعت فيه الجريمة وينشر الحكم في جريدتين يوميتين واسعتي الانتشار على نفقة المحكوم عليه . كما يقتضى ما يحكم به من غرامات أو رد أو تعويضات من قيمة خطاب الضمان المنصوص عليه في البند (3) من المادة (22) من هذا القانون وتتبع القواعد المقررة للتنفيذ فيما يزيد عن تلك القيمة ."}, {"number": "245", "chapter": "الباب الثانى", "text": "يعاقب كل من يخالف أياً من أحكام الفصل الثاني من الباب الأول من الكتاب الثاني بشأن تنظيم عمل الأجانب والقرارات الوزارية الصادرة تنفيذاً له بغرامة لا تقل عن خمسمائة جنيه ولا تجاوز خمسة آلاف جنيه . وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة وتضاعف الغرامة في حالة العود ."}, {"number": "246", "chapter": "الباب الثانى", "text": "يعاقب صاحب العمل أومن يمثله عن المنشأة الذى يخالف حكم المادة (32) من هذا القانون بغرامة لا تقل عن خمسين جنيهاً ولا تجاوز مائة جنيه . وتتعدد الغرامة بتعدد العمال الذين وقعت في شأنهم الجريمة وتضاعف الغرامة في حالة العود ."}, {"number": "248", "chapter": "الباب الثانى", "text": "يعاقب صاحب العمل أو من يمثله عن المنشأة الذى يخالف أياً من أحكام المواد ( 73 فقرة ثانية ، 74 ، 75 ، 89 ، 90 ، 98 ، 99 ، 101 ، 102 ) من هذا القانون والقرارات الوزارية المنفذة لها بغرامة لا تقل عن خمسمائة جنيه ولا تجاوز ألف جنيه . وتتعدد الغرامة بتعدد العمال الذين وقعت في شأنهم الجريمة وتضاعف الغرامة في حالة العود ."}, {"number": "مستبدلة بالقانون رقم", "chapter": "الباب الثانى", "text": "90 لسنة 2005"}, {"number": "249", "chapter": "الباب الثانى", "text": "يعاقب صاحب العمل أو من يمثله عن المنشأة الذى يخالف أياً من أحكام المواد ( 76 ، 77 ، 78 ، 79 ، 80 ، 81 ، 82 ، 83 ، 84 ، 85 ، 86 ، 87 ، 88 ، 91 ، 92 ، 93 ، 94 ، 95 ، 96 ، 139 ، 140 ، 142 ، 144 ) من هذا القانون والقرارات الوزارية المنفذة لها بغرامة لا تقل عن مائة جنيه ولا تجاوز مائتى جنيه . وتتعدد الغرامة بتعدد العمال الذين وقعت في شأنهم الجريمة وتضاعف الغرامة في حالة العود ."}, {"number": "250", "chapter": "الباب الثانى", "text": "يعاقب صاحب العمل أو من يمثله عن المنشأة الذى يخالف أياً من أحكام المواد ( 110 ، 111 ، 113 ، 116 ، 118 ، 119 ، 123 ، 124 ، 126 ، 127 ، 130) من هذا القانون والقرارات الوزارية المنفذة لها بغرامة لا تقل عن مائتى جنيه ولا تجاوز خمسمائة جنيه . وتتعدد الغرامة بتعدد العمال الذين وقعت فى شأنهم الجريمة وتضاعف الغرامة في حالة العود ."}, {"number": "251", "chapter": "الباب الثانى", "text": "يعاقب كل من يخالف أياً من أحكام المواد ( 135 ، 136 ، 137 ، 138 ) من هذا القانون بغرامة لا تقل عن خمسمائة جنيه ولا تجاوز ألفي جنيه . وعند الحكم بالإدانة يقضى وجوبياً بإغلاق المنشأة ."}, {"number": "252", "chapter": "الباب الثانى", "text": "يعاقب كل من يخالف أياً من أحكام المواد ( 149 ، 150 ، 157 ) من هذا القانون بغرامة لا تقل عن مائتى جنيه ولا تجاوز خمسمائة جنيه ."}, {"number": "253", "chapter": "الباب الثانى", "text": "يعاقب كل من يخالف حكم المادة (169) من هذا القانون بغرامة لا تقل عن ألف جنيه ولا تجاوز خمسة آلاف جنيه ."}, {"number": "254", "chapter": "الباب الثانى", "text": "يعاقب صاحب العمل أو من يمثله عن المنشأة الذي يخالف حكم المادة ( 196) من هذا القانون بغرامة لا تقل عن ألف جنيه ولا تجاوز ألفي جنيه . وتتعدد الغرامة بتعدد العمال الذين وقعت في شأنهم الجريمة وتضاعف الغرامة في حالة العود ."}, {"number": "255", "chapter": "الباب الثانى", "text": "يعاقب صاحب العمل أو من يمثله عن المنشأة الذى يخالف أياً من أحكام المواد ( 197 ، 198 ، 200 ) من هذا القانون بغرامة لا تقل عن خمسمائة جنيه ولا تجاوز ألف جنيه ."}, {"number": "256", "chapter": "الباب الثانى", "text": "يعاقب كل من يخالف أياً من أحكام الكتاب الخامس بشأن السلامة والصحة المهنية وتأمين بيئة العمل والقرارات الصادرة تنفيذاً له بالحبس مدة لا تقل عن ثلاثة أشهر وبغرامة لا تقل عن ألف جنيه ولا تجاوز عشرة آلاف جنيه أو بإحدى هاتين العقوبتين . وتكون عقوبتا الحبس والغرامة المنصوص عليهما في الفقرة السابقة وجوبيتين إذا ترتب على الجريمة الوفاة أو الإصابة الجسيمة . وتضاعف الغرامة في حالة العودة . ويكون صاحب العمل أو من يمثله عن المنشأة مسئولاً بالتضامن مع المحكوم عليه في الوفاء بالعقوبات المالية إذا كانت الجريمة قد وقعت نتيجة إخلاله بأي من الواجبات التي يفرضها عليه هذا القانون ."}, {"number": "257", "chapter": "الباب الثانى", "text": "يعاقب صاحب العمل أو من يمثله عن المنشأة الذى يخالف أياً من أحكام المادتين (234) ، (235) من هذا القانون بغرامة لا تقل عن خمسمائة جنيه ولا تجاوز ألف جنيه ، وتضاعف الغرامة في حالة العود ."}]};